-- CASE 037: case-solving content rebuild.
-- Generated by case/compile.mjs from case/model. Do not edit by hand.
--
-- What changes
--   * Every lead is rewritten as a step in one investigation: the answers are
--     claims about the case, each reached from evidence held by different seats.
--   * answer_metadata.alternatives: accepted variants. Comparison ignores case,
--     spacing and punctuation (S01-TUN = S01 TUN = s01tun).
--   * answer_metadata.redact = false: evidence may legitimately contain the
--     claim's own words (a register that names the institution), so the
--     server-side redaction is switched off for those leads. The authoring
--     validator keeps the answer out of every instruction, hint and objective.
--   * Four hint levels (THINK / FOCUS / DEDUCE / CONFIRM); the fourth costs 15 min.
--   * A lead can file several exhibits (metadata.evidenceBundle).
--   * Evidence is replaced by the exhibits the new case needs.

-- 1. Four hint levels
UPDATE game_config SET value = value || '{"hint4": 900}'::jsonb WHERE key = 'hint_penalties';
CREATE OR REPLACE FUNCTION request_hint(
  p_node_id UUID,
  p_hint_number INTEGER
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_team_id UUID;
  v_team_status team_status;
  v_hint_used BOOLEAN;
  v_hint_available BOOLEAN;
  v_penalty INTEGER;
  v_max_hints INTEGER;
  v_penalties JSONB;
  hint_content TEXT;
  v_content JSONB;
BEGIN
  IF p_hint_number IS NULL OR p_hint_number < 1 THEN
    RETURN jsonb_build_object('error', 'Invalid hint number');
  END IF;

  SELECT team_id INTO v_team_id
  FROM players
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_team_id IS NULL THEN
    RETURN jsonb_build_object('error', 'No team found');
  END IF;

  SELECT status INTO v_team_status
  FROM teams
  WHERE id = v_team_id;

  IF v_team_status <> 'ACTIVE' THEN
    RETURN jsonb_build_object('error', 'Game not active');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM node_progress
    WHERE team_id = v_team_id
    AND node_id = p_node_id
    AND status IN ('AVAILABLE', 'IN_PROGRESS')
  ) INTO v_hint_available;

  IF NOT v_hint_available THEN
    RETURN jsonb_build_object('error', 'Node not available for hints');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM hints_used
    WHERE team_id = v_team_id AND node_id = p_node_id AND hint_number = p_hint_number
  ) INTO v_hint_used;

  IF v_hint_used THEN
    RETURN jsonb_build_object('error', 'Hint already used');
  END IF;

  -- Cap and penalties are configuration, not literals.
  SELECT value INTO v_penalties
  FROM game_config
  WHERE key = 'hint_penalties';

  v_max_hints := COALESCE(jsonb_array_length((SELECT content->'hints' FROM puzzle_nodes WHERE id = p_node_id)), 0);
  v_max_hints := LEAST(v_max_hints, 4);

  IF p_hint_number > v_max_hints THEN
    RETURN jsonb_build_object('error', 'Hint not available');
  END IF;

  SELECT content INTO v_content
  FROM puzzle_nodes
  WHERE id = p_node_id;

  -- Hints are served one at a time and never in bulk: returning the array
  -- would hand the player every remaining hint, including the last one that
  -- states the answer outright.
  hint_content := v_content->'hints'->>(p_hint_number - 1);

  IF hint_content IS NULL THEN
    RETURN jsonb_build_object('error', 'Hint not available');
  END IF;

  v_penalty := COALESCE(
    (v_penalties->>('hint' || p_hint_number))::INTEGER,
    0
  );

  INSERT INTO hints_used (team_id, node_id, hint_number, time_penalty_seconds)
  VALUES (v_team_id, p_node_id, p_hint_number, v_penalty);

  UPDATE node_progress
  SET hints_used = hints_used + 1,
      time_spent_seconds = time_spent_seconds + v_penalty,
      updated_at = now()
  WHERE team_id = v_team_id AND node_id = p_node_id;

  UPDATE team_progress
  SET hints_used = hints_used + 1
  WHERE team_id = v_team_id;

  INSERT INTO notifications (team_id, target_roles, type, title, message)
  VALUES (v_team_id, ARRAY['OBSERVER', 'ANALYST', 'OPERATOR'],
          'HINT_AVAILABLE', 'Hint Used',
          'Time penalty: ' || (v_penalty / 60) || ' minutes applied.');

  INSERT INTO game_events (type, team_id, node_id, payload)
  VALUES ('HINT_CONSUMED', v_team_id, p_node_id,
          jsonb_build_object('hintNumber', p_hint_number, 'penaltySeconds', v_penalty));

  RETURN jsonb_build_object(
    'hint', hint_content,
    'penaltySeconds', v_penalty
  );
END;
$$;

-- 2. submit_puzzle_answer: alternatives, loose comparison, evidence bundles
CREATE OR REPLACE FUNCTION submit_puzzle_answer(
  p_node_id UUID,
  p_answer TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_team_id UUID;
  v_player_id UUID;
  v_player_role player_role;
  v_team_status team_status;
  v_game_started_at TIMESTAMPTZ;
  v_answer_meta JSONB;
  v_rewards JSONB;
  v_branches JSONB;
  v_progress RECORD;
  v_normalized_answer TEXT;
  v_accepted TEXT;
  v_is_correct BOOLEAN;
  v_attempt_number INTEGER;
  v_response_time INTEGER;
  v_points_awarded INTEGER;
  v_recent_submissions INTEGER;
  v_base_points INTEGER;
  v_next_code TEXT;
  v_next_uuid UUID;
  v_reveal JSONB;
  v_node_meta JSONB;
  v_evidence_code TEXT;
  v_is_final BOOLEAN := false;
  result JSONB;
  MAX_SUBMISSIONS_PER_MINUTE CONSTANT INTEGER := 5;
BEGIN
  SELECT team_id, id, role INTO v_team_id, v_player_id, v_player_role
  FROM players
  WHERE auth_user_id = auth.uid()
  LIMIT 1;

  IF v_team_id IS NULL THEN
    RETURN jsonb_build_object('error', 'No team found for player');
  END IF;

  SELECT status, game_started_at
    INTO v_team_status, v_game_started_at
    FROM teams
   WHERE id = v_team_id;

  IF v_team_status <> 'ACTIVE' THEN
    RETURN jsonb_build_object('error', 'Game not active');
  END IF;

  v_response_time := GREATEST(
    0,
    EXTRACT(EPOCH FROM (now() - v_game_started_at))::INTEGER
  );

  SELECT COUNT(*) INTO v_recent_submissions
  FROM submissions
  WHERE team_id = v_team_id
  AND submitted_at > now() - INTERVAL '1 minute';

  IF v_recent_submissions >= MAX_SUBMISSIONS_PER_MINUTE THEN
    RETURN jsonb_build_object('error', 'Rate limited. Please wait before submitting again.');
  END IF;

  -- answer_metadata is server-only and is never returned to the client.
  SELECT answer_metadata, rewards, branches, metadata
    INTO v_answer_meta, v_rewards, v_branches, v_node_meta
  FROM puzzle_nodes
  WHERE id = p_node_id
    AND id IN (
      SELECT node_id FROM node_progress
      WHERE team_id = v_team_id
      AND status IN ('AVAILABLE', 'IN_PROGRESS')
    );

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Node not accessible');
  END IF;

  SELECT * INTO v_progress
  FROM node_progress
  WHERE team_id = v_team_id AND node_id = p_node_id;

  IF NOT FOUND THEN
    INSERT INTO node_progress (team_id, node_id, status)
    VALUES (v_team_id, p_node_id, 'IN_PROGRESS')
    RETURNING * INTO v_progress;
  END IF;

  v_attempt_number := v_progress.attempts + 1;

  -- Normalize both sides identically: upper-case, trim, collapse inner runs
  -- of whitespace. This makes "exact" and "case_insensitive" equivalent,
  -- which is the behaviour the seed's validationMethod values describe.
  v_normalized_answer := UPPER(TRIM(p_answer));
  v_normalized_answer := REGEXP_REPLACE(v_normalized_answer, '\s+', ' ', 'g');

  v_accepted := UPPER(TRIM(COALESCE(v_answer_meta->>'acceptedAnswer', '')));
  v_accepted := REGEXP_REPLACE(v_accepted, '\s+', ' ', 'g');

  v_is_correct := (
    v_accepted <> ''
    AND (
      v_normalized_answer = v_accepted
      OR (
        char_length(regexp_replace(v_normalized_answer, '[^A-Z0-9]', '', 'g')) > 0
        AND (
          regexp_replace(v_normalized_answer, '[^A-Z0-9]', '', 'g') = regexp_replace(v_accepted, '[^A-Z0-9]', '', 'g')
          OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements_text(COALESCE(v_answer_meta->'alternatives', '[]'::jsonb)) AS alt(value)
             WHERE regexp_replace(UPPER(alt.value), '[^A-Z0-9]', '', 'g') = regexp_replace(v_normalized_answer, '[^A-Z0-9]', '', 'g')
          )
        )
      )
      OR EXISTS (
        SELECT 1
          FROM jsonb_array_elements_text(COALESCE(v_answer_meta->'alternatives', '[]'::jsonb)) AS alt(value)
         WHERE UPPER(TRIM(alt.value)) = v_normalized_answer
      )
    )
  );

  v_base_points := COALESCE((v_rewards->>'points')::INTEGER, 0);

  v_points_awarded := CASE
    WHEN NOT v_is_correct THEN 0
    WHEN v_attempt_number = 1 THEN v_base_points
    WHEN v_attempt_number = 2 THEN (v_base_points + 1) / 2
    ELSE 0
  END;

  INSERT INTO submissions (
    team_id, node_id, player_id, role, submitted_answer,
    normalized_answer, is_correct, attempt_number,
    response_time_seconds, points_awarded
  ) VALUES (
    v_team_id, p_node_id, v_player_id, v_player_role, p_answer,
    v_normalized_answer, v_is_correct, v_attempt_number,
    v_response_time, v_points_awarded
  );

  UPDATE node_progress
  SET attempts = v_attempt_number,
      updated_at = now()
  WHERE team_id = v_team_id AND node_id = p_node_id;

  IF v_is_correct THEN
    UPDATE node_progress
    SET status = 'SOLVED',
        solved_at = now(),
        solved_answer = v_normalized_answer,
        attempts = v_attempt_number,
        time_spent_seconds = time_spent_seconds + v_response_time,
        points_awarded = v_points_awarded
    WHERE team_id = v_team_id AND node_id = p_node_id;

    UPDATE teams
    SET score = score + v_points_awarded
    WHERE id = v_team_id;

    -- Mirror the solved node into the team's aggregate progress so the
    -- player's map and counter update without a second round trip.
    UPDATE team_progress
    SET solved_nodes = (
          SELECT COALESCE(jsonb_agg(jsonb_build_array(np.node_id)), '[]'::jsonb)
          FROM node_progress np
          WHERE np.team_id = v_team_id AND np.status = 'SOLVED'
        ),
        score = (SELECT score FROM teams WHERE id = v_team_id)
    WHERE team_id = v_team_id;

    v_next_code := NULLIF(v_branches->>'unlocks', '');
    IF v_next_code IS NOT NULL THEN
      SELECT id INTO v_next_uuid
      FROM puzzle_nodes
      WHERE code = v_next_code;

      IF v_next_uuid IS NOT NULL THEN
        -- DO UPDATE, not DO NOTHING: bureau_reset_node() pre-creates every
        -- node as LOCKED, so the row usually already exists. With DO NOTHING
        -- the freshly unlocked node stayed LOCKED and get_player_node_detail
        -- kept answering {unlocked:false}, stalling the game after one puzzle.
        -- A node that was already solved or in progress keeps its status.
        INSERT INTO node_progress (team_id, node_id, status)
        VALUES (v_team_id, v_next_uuid, 'AVAILABLE')
        ON CONFLICT (team_id, node_id) DO UPDATE
        SET status = 'AVAILABLE',
            updated_at = now()
        WHERE node_progress.status = 'LOCKED';

        UPDATE teams
        SET current_node_id = v_next_uuid,
            current_node_code = v_next_code
        WHERE id = v_team_id;

        UPDATE team_progress
        SET current_node_id = v_next_uuid,
            current_node_code = v_next_code
        WHERE team_id = v_team_id;
      END IF;
    END IF;

    INSERT INTO game_events (type, team_id, player_id, node_id, payload)
    VALUES ('NODE_SOLVED', v_team_id, v_player_id, p_node_id,
            jsonb_build_object('points', v_points_awarded, 'attempts', v_attempt_number));

    -- A node with nothing after it is the end of the case. Nothing used to
    -- close it: the last solve left the team ACTIVE on a hub that offered the
    -- solved lead again, and the ending screens were unreachable.
    IF v_next_code IS NULL THEN
      v_is_final := true;
      UPDATE teams
      SET status = 'COMPLETED',
          completed_at = now()
      WHERE id = v_team_id AND status = 'ACTIVE';

      INSERT INTO game_events (type, team_id, player_id, node_id, payload)
      VALUES ('TEAM_COMPLETED', v_team_id, v_player_id, p_node_id,
              jsonb_build_object('points', v_points_awarded));
    END IF;

    -- File the material this lead recovered. The earliest version of this
    -- function did; the rewrites that fixed scoring and unlocking dropped it,
    -- so the evidence archive of a real team stayed empty however many leads
    -- it closed.
    v_evidence_code := v_node_meta->'evidenceUnlocked'->>'id';
    -- A lead files every exhibit in its bundle (or, for older leads, its one exhibit).
    UPDATE team_progress tp
       SET evidence_owned = COALESCE((
             SELECT array_agg(DISTINCT x)
               FROM unnest(tp.evidence_owned || COALESCE((
                      SELECT array_agg(e.id)
                        FROM evidence e
                       WHERE e.code IN (
                         SELECT jsonb_array_elements_text(
                                  COALESCE(v_node_meta->'evidenceBundle', jsonb_build_array(v_evidence_code)))
                       )
                    ), '{}'::uuid[])) AS x
           ), '{}'::uuid[])
     WHERE tp.team_id = v_team_id;

    v_reveal := nexus_node_reveal(p_node_id);

    INSERT INTO notifications (team_id, target_roles, type, title, message)
    VALUES (v_team_id, ARRAY['OBSERVER', 'ANALYST', 'OPERATOR'],
            'PUZZLE_SOLVED',
            CASE WHEN v_is_final THEN 'CASE CLOSED' ELSE 'LEAD CLOSED' END,
            CASE WHEN v_is_final THEN 'Your unit filed the last entry.' ELSE 'Your unit closed a lead.' END);

    result := jsonb_build_object(
      'isCorrect', true,
      'pointsAwarded', v_points_awarded,
      'attemptNumber', v_attempt_number,
      'nextNodeId', v_next_uuid,
      'nextNodeCode', v_next_code,
      'isFinal', v_is_final,
      'reveal', v_reveal
    );
  ELSE
    INSERT INTO game_events (type, team_id, player_id, node_id, payload)
    VALUES ('SUBMISSION_MADE', v_team_id, v_player_id, p_node_id,
            jsonb_build_object('correct', false, 'attempt', v_attempt_number));

    result := jsonb_build_object(
      'isCorrect', false,
      'pointsAwarded', 0,
      'attemptNumber', v_attempt_number
    );
  END IF;

  RETURN result;
END;
$$;

-- 3. get_player_node_detail: per-lead redaction opt-out
CREATE OR REPLACE FUNCTION get_player_node_detail(
  p_node_id UUID,
  p_player_role TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  v_team_id UUID;
  v_actual_role TEXT;
  v_is_unlocked BOOLEAN;
  v_node RECORD;
  v_role_key TEXT;
  v_role_content JSONB;
  v_investigation JSONB;
  v_resolved_location TEXT;
  v_resolved_status TEXT;
  v_solved_node RECORD;
  v_redact_key TEXT;
BEGIN
  SELECT pl.team_id, pl.role::text INTO v_team_id, v_actual_role
  FROM players pl
  WHERE pl.auth_user_id = auth.uid()
  LIMIT 1;

  IF v_team_id IS NULL THEN
    RETURN jsonb_build_object('unlocked', false);
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM node_progress
    WHERE team_id = v_team_id
    AND node_id = p_node_id
    AND status IN ('AVAILABLE', 'IN_PROGRESS')
  ) INTO v_is_unlocked;

  IF NOT v_is_unlocked THEN
    -- A solved lead is not locked: it is closed. Say so, and return what it
    -- revealed, so the team can read it again. Before this a solved node
    -- answered {unlocked:false}, which the app could not tell apart from a
    -- node that was never issued.
    IF EXISTS (
      SELECT 1 FROM node_progress
      WHERE team_id = v_team_id AND node_id = p_node_id AND status = 'SOLVED'
    ) THEN
      SELECT code, title, stage, location INTO v_solved_node
        FROM puzzle_nodes WHERE id = p_node_id;
      RETURN jsonb_build_object(
        'unlocked', false,
        'solved', true,
        'code', v_solved_node.code,
        'title', v_solved_node.title,
        'stage', v_solved_node.stage,
        'location', v_solved_node.location,
        'reveal', nexus_node_reveal(p_node_id)
      );
    END IF;
    RETURN jsonb_build_object('unlocked', false);
  END IF;

  SELECT code, title, type, difficulty, estimated_minutes, location, stage,
         content, metadata, rewards, answer_metadata
    INTO v_node
    FROM puzzle_nodes
   WHERE id = p_node_id;

  IF v_node.code IS NULL THEN
    RETURN jsonb_build_object('unlocked', false);
  END IF;

  -- Leads whose evidence legitimately contains the claim's own words opt out
  -- of redaction (answer_metadata.redact = false). The authoring validator
  -- guarantees the answer is absent from objectives, prompts and hints.
  v_redact_key := CASE
    WHEN COALESCE(v_node.answer_metadata->>'redact', 'true') = 'false' THEN NULL
    ELSE v_node.answer_metadata->>'acceptedAnswer'
  END;

  -- Resolve the runtime location: prefer admin override, fall back to node's
  -- static location column.
  SELECT rl.location_name, rl.location_status
  INTO v_resolved_location, v_resolved_status
  FROM resolve_node_location(p_node_id) rl;

  IF v_resolved_location IS NULL THEN
    v_resolved_location := v_node.location;
  END IF;

  -- The caller's role comes from the database, never from the request.
  v_role_key := UPPER(v_actual_role);

  v_role_content := COALESCE(v_node.content -> LOWER(v_role_key), '{}'::jsonb);

  v_investigation := CASE
    WHEN v_role_key = 'OPERATOR' THEN v_node.content -> 'operatorInvestigation'
    ELSE NULL
  END;

  RETURN jsonb_build_object(
    'unlocked', true,
    'code', v_node.code,
    'title', v_node.title,
    'type', v_node.type::text,
    'difficulty', v_node.difficulty,
    'estimatedMinutes', v_node.estimated_minutes,
    'location', v_resolved_location,
    'locationStatus', v_resolved_status,
    'stage', v_node.stage,
    'narrativeObjective', nexus_redact_answer(v_node.content->>'narrativeObjective', v_redact_key),
    'roleDependencyLevel', v_node.content->>'roleDependencyLevel',
    'roleContent', nexus_redact_jsonb(v_role_content, v_redact_key),
    'operatorInvestigation', nexus_redact_jsonb(v_investigation, v_redact_key),
    'coordinationChain', nexus_redact_jsonb(v_node.content->'coordinationChain', v_redact_key),
    'failurePropagation', nexus_redact_jsonb(v_node.content->'failurePropagation', v_redact_key),
    'whyTeamworkMatters', nexus_redact_answer(v_node.metadata->>'whyTeamworkMatters', v_redact_key),
    'branchConditions', COALESCE(v_node.content->'branchConditions', '[]'::jsonb),
    'points', COALESCE((v_node.rewards->>'points')::INTEGER, 0)
  );
END;
$$;

-- 4. Leads
UPDATE puzzle_nodes SET
  title = $nxs$The Mark$nxs$,
  content = $nxj${"hints":["This is a question about who something belonged to. A mark on stone is a claim of ownership; a register is where such claims were written down.","The Observer and Analyst together produce a mark. The Operator’s register is organised by marks, not by names.","Match the decoded mark to its row, then compare the issue year on that row with the years on the other rows. The question asks who held the building first.","One word, an institution’s name as it appears in the register. It is neither the Bureau nor the university."],"observer":{"role":"OBSERVER","screenTitle":"Facade Field Log","visualType":"visual","whatTheySee":"A row of carved stone glyphs above the main entrance. Eight columns of symbols; some shapes repeat.","taskPrompt":"Copy the row left to right, one glyph per column, and read it to the Analyst. Say if any column looks different from the rest.","dataPayload":"FIELD LOG — MAIN ENTRANCE\nFACADE SYMBOL GRID: 8 columns of carved stone symbols above the doors.\nThe stonework is original to the 1974 building. Count the columns yourself before you read; the Analyst cannot check your count from where they sit."},"analyst":{"role":"ANALYST","screenTitle":"Mark Decoder","visualType":"memory-recall","whatTheySee":"The cipher wheel from your kit, which maps the facade’s glyph shapes to letters.","taskPrompt":"Turn each glyph your Observer reads into a letter with the wheel, and read the letters back in order. A mark is seven letters; the wheel will not give a letter for a column that is not part of it.","dataPayload":"DECODING INSTRUCTIONS: Convert each glyph to a single letter using the substitution key.\nThe Institute’s bay marks were always seven letters. Report what the wheel gives you, in order, and say which column it would not translate."},"operator":{"role":"OPERATOR","screenTitle":"Register of Marks","visualType":"document-forensics","whatTheySee":"A terminal holding a scanned register of institutional marks, 1974 issue, and the Bureau’s bulletin of 18 October.","taskPrompt":"Match the mark your Analyst decodes to a row in the register, check the dates on that row against the bulletin, and answer who held the building before the university.","dataPayload":"The register is keyed by mark. The bulletin names the building as the university’s Admin Building.\nQUESTION: Whose building was this before the university?\nANSWER (ONE WORD — the institution’s name): [ _ _ _ _ _ _ ]","interactiveData":{"documentText":"REGISTER OF INSTITUTIONAL MARKS — 1974 ISSUE (extract)\n\nMARK      HOLDER                                         ISSUED   NOTE\nCDFDEFF   Halder Institute for Continuity Studies        1974     Admin Bldg, main + east wing\nDBFFECD   Estates Office                                 1974     Annex B only\nCEEDFDC   Printing & Stores                              1974     Basement, west\nFDCEFDE   Plant & Heating                                1974     Sub-basement\nBDFCEED   Bureau of Continuity Records                   1998     Retention desk, tenant of Admin Bldg\nCDFDEEF   University Estates (consolidated)              1998     All other bays\n\nCountermarks: see Addendum A (restricted).\n\nBULLETIN MP-24-018, 18 OCT 2024 09:40\n\"The Admin Building, university estate…\""}},"branchConditions":[],"coordinationChain":{"observerProduces":"The glyph row, column by column, and which column stands apart.","analystTransforms":"Glyphs into a seven-letter mark with the wheel.","operatorExecutes":"Looks the mark up in the register, checks the issue dates, and files the claim."},"failurePropagation":{"wrongStep":"Matching the building to the Bureau because it is the tenant that still keeps records here, or to the university because it holds the estate today.","consequence":"The claim is rejected: the register dates those holders to 1998.","recoveryGuidance":"Read the issue year on the row for the facade’s own mark, not the name of whoever is in the building now."},"narrativeObjective":"The bulletin calls this the university’s Admin Building. The stone above the doors says something older. Establish who built and held the building before the university.","roleDependencyLevel":"D2","operatorInvestigation":{"operatorOwnEvidence":"Your terminal holds: Register of Marks.","requiredDiscoveries":{"observerDiscovery":"The glyph row, column by column, and which column stands apart.","analystDiscovery":"Glyphs into a seven-letter mark with the wheel."},"operatorTaskDescription":"Whose building was this before the university?"}}$nxj$::jsonb,
  metadata = $nxj${"time":"6m","type":"OBSERVATION","feeds":"M01","difficulty":2,"storyReveal":"The mark above the doors is not the university’s. The Admin Building was raised for an institute that no longer exists. What remains of it is a records desk that kept its retention rules.","locationClue":{"format":"Inference","clueText":"A place built to keep records kept its time as carefully. In the lobby, one clock is wrong in a way that looks deliberate.","solution":"Main Building Lobby Archive Alcove","nextQrNode":"QR-NODE-02","explanation":"Directs teams from the entrance facade into the archive alcove.","nextPhysicalLocation":"[ADMIN BUILDING] — Lobby Archive Alcove"},"evidenceUnlocked":{"id":"EVID-P01","state":"RECOVERED","title":"Register of Institutional Marks, 1974","source":"Archive alcove, lobby","content":"A scanned register of marks and the offices that held them, with an addendum reference.","category":"Document","timestamp":"Act 1"},"whyTeamworkMatters":"The glyph row, column by column, and which column stands apart. Glyphs into a seven-letter mark with the wheel. Looks the mark up in the register, checks the issue dates, and files the claim.","evidenceBundle":["EVID-P01"],"act":1,"mechanic":"provenance"}$nxj$::jsonb,
  answer_metadata = $nxj${"acceptedAnswer":"HALDER","alternatives":["HALDER INSTITUTE","THE HALDER INSTITUTE","HALDER INSTITUTE FOR CONTINUITY STUDIES"],"validationMethod":"case_insensitive","redact":false,"question":"Whose building was this before the university?","format":"ONE WORD (the institution’s name)","fullSolution":"Observer reads the glyph row; Analyst decodes to CDFDEFF with the wheel (the eighth column is not a letter); Operator finds CDFDEFF in the 1974 register: Halder Institute for Continuity Studies, issued 1974. The Estates Office and University Estates marks are 1998; the Bureau is a 1998 tenant. Answer: HALDER."}$nxj$::jsonb
WHERE code = $nxs$P01$nxs$;
UPDATE puzzle_nodes SET
  title = $nxs$The Held Moment$nxs$,
  content = $nxj${"hints":["A clock that is wrong on purpose is a record. Ask what it is recording, and who would want it held.","The Analyst’s card names an entry in the Operator’s register. The Observer’s reading is the check that you have the right moment.","The face reads 9:47 and has no marker for morning or evening. The register’s time for the entry the card cites, in 24-hour form, must give 9:47 on a twelve-hour face.","Hours and minutes with a colon. It is later in the day than the entry that says L.V. left."],"observer":{"role":"OBSERVER","screenTitle":"Lobby Clock Log","visualType":"observation","whatTheySee":"A vintage clock face with Roman numerals. One hand points at IX, the other at VII.","taskPrompt":"Read the face from the east side of the lobby and report the time it shows. Then report anything you can see about the clock’s condition: dust, marks, whether anything is moving.","dataPayload":"OBSERVATION: The clock face shows 9:47 when viewed from the east side.\nIt is a twelve-hour face. Nothing on it says morning or evening."},"analyst":{"role":"ANALYST","screenTitle":"Facilities Clock Card","visualType":"document-forensics","whatTheySee":"The maintenance card for the lobby clock, as kept by Facilities.","taskPrompt":"Read the card for what was done to the clock and why. Say whether the clock is running.","dataPayload":"Card LC-01, one entry from the night of the 17th. The Operator holds the register the entry refers to.","interactiveData":{"documentText":"LOBBY CLOCK — MAINTENANCE CARD LC-01\n\n17 OCT 2024  22:45\nFace set by hand to the time entered against SQ-24-001 in the guard-desk register (evening entry).\nMovement isolated at the gear train. Clock is NOT to be reset or restarted without a Facilities ticket.\n— N. Rahal, Facilities"}},"operator":{"role":"OPERATOR","screenTitle":"Guard-Desk Register","visualType":"document-forensics","whatTheySee":"A scan of the guard-desk register page for 17 October 2024.","taskPrompt":"Find the register entry that the clock card refers to and read its time. The register keeps 24-hour time; the clock is a twelve-hour face.","dataPayload":"REGISTER PAGE GD-241017 (extract). The clock is held at a moment, not at the time now.\nQUESTION: What time is the lobby clock holding?\nANSWER (HH:MM, 24-hour): [ _ _ : _ _ ]","interactiveData":{"documentText":"GUARD DESK — ADMIN BUILDING — 17 OCT 2024\n\n08:02  IN   staff (14)\n12:30  IN/OUT contractor, lift service\n17:28  OUT  L.V. (badge, main entrance)\n18:15  OUT  night cleaners IN\n21:44  QUORUM ATTEST begins   (SQ-24-001)\n21:47  SQ-24-001 APPLIED  tri-attest\n22:45  Facilities, lobby clock (LC-01)\n23:10  OUT  Facilities\n\nNo further main-entrance badge events recorded for the night."}},"branchConditions":[],"coordinationChain":{"observerProduces":"The time on the clock face, read from the east side, and its condition.","analystTransforms":"What the card says Facilities did, and which register entry it points to.","operatorExecutes":"Finds that entry, converts it to 24-hour time and files the claim."},"failurePropagation":{"wrongStep":"Answering with the time on the face, or the time of the Facilities entry that set it.","consequence":"The claim is rejected: the face is twelve-hour and the set-time is when someone touched the clock, not what it holds.","recoveryGuidance":"The clock holds the time written against the register entry the card names, in the register’s 24-hour form."},"narrativeObjective":"A clock that shows the wrong time is either broken or has been set on purpose. Establish which moment the lobby clock was set to hold, and when that moment happened.","roleDependencyLevel":"D2","operatorInvestigation":{"operatorOwnEvidence":"Your terminal holds: Guard-Desk Register.","requiredDiscoveries":{"observerDiscovery":"The time on the clock face, read from the east side, and its condition.","analystDiscovery":"What the card says Facilities did, and which register entry it points to."},"operatorTaskDescription":"What time is the lobby clock holding?"}}$nxj$::jsonb,
  metadata = $nxj${"time":"5m","type":"SPATIAL","feeds":"P01","difficulty":2,"storyReveal":"Facilities stopped the lobby clock on purpose, at the moment of an entry made against SQ-24-001. That moment is over four hours after the bulletin says she left the building.","locationClue":{"format":"Inference","clueText":"The Institute cut numbers into the foot of its own entrance, in brass, where anyone could read them. A door somewhere is waiting for those numbers.","solution":"Main Hall Central Staircase","nextQrNode":"QR-NODE-03","explanation":"Directs teams from the clock tower to the Main Hall.","nextPhysicalLocation":"[MAIN HALL] — Central Staircase"},"evidenceUnlocked":{"id":"EVID-P02","state":"RECOVERED","title":"Lobby Clock Maintenance Card LC-01","source":"Behind the lobby clock face","content":"Facilities maintenance card for the lobby clock with a single entry for 17 October 2024.","category":"Note","timestamp":"Act 1"},"whyTeamworkMatters":"The time on the clock face, read from the east side, and its condition. What the card says Facilities did, and which register entry it points to. Finds that entry, converts it to 24-hour time and files the claim.","evidenceBundle":["EVID-P02","EVID-P02-B"],"act":1,"mechanic":"timeline"}$nxj$::jsonb,
  answer_metadata = $nxj${"acceptedAnswer":"21:47","alternatives":["2147","21.47","9:47 PM","09:47 PM","9:47PM","21:47:00"],"validationMethod":"case_insensitive","redact":false,"question":"What time is the lobby clock holding?","format":"HH:MM, 24-hour clock","fullSolution":"The face shows 9:47 (twelve-hour). Card LC-01 says Facilities set it to the time entered against SQ-24-001 (evening entry) and stopped the movement. Register GD-241017 logs SQ-24-001 applied at 21:47. 21:47 on a twelve-hour face is 9:47; 09:47 would be an AM entry, and the register shows none. Answer: 21:47."}$nxj$::jsonb
WHERE code = $nxs$P02$nxs$;
UPDATE puzzle_nodes SET
  title = $nxs$Bay 3425$nxs$,
  content = $nxj${"hints":["A number cut into stone is a public number. Ask what it opens, and who could have read it.","Four plates, a table that pairs letters with digits, and a directory of rooms. The Analyst’s ordering decides which room.","Recall the mark from the entrance. Order the plates by where each letter pairs and first appears, then look the number up.","A room name as the directory gives it. It is not in the Admin Building."],"observer":{"role":"OBSERVER","screenTitle":"Steps Field Log","visualType":"visual","whatTheySee":"Four worn brass plates near the facade steps. Each shows a single digit.","taskPrompt":"Read the digit on each plate and report the plates in the order they lie on the steps. Say which plate is most worn.","dataPayload":"BASE DETAILS: Four worn brass plates near the facade steps each show a single digit.\nBrass plates embedded in the steps: 3, 4, 2, 5.\nTreat the plates as four separate readings. Whether their order on the steps is the order that matters is for the Analyst."},"analyst":{"role":"ANALYST","screenTitle":"Bay Table","visualType":"document-forensics","whatTheySee":"The Institute’s bay table, which pairs mark letters with digits, and the mark you decoded earlier.","taskPrompt":"Use the bay table to put the plates in the order the mark gives them, and read the four digits back to the Operator.","dataPayload":"Recall the mark your unit decoded at the entrance. Bay numbers were derived from it.","interactiveData":{"requiresPuzzle":"P01","recallPrompt":"Recall the seven-letter mark decoded at the facade.","documentText":"HALDER BAY TABLE (derivation)\n\nA bay number is four digits.\nTake the letters of the Institute’s mark in the order each first appears.\nPair each with its digit:  C = 3   D = 4   E = 5   F = 2\nRead the digits in that order.\n\nORDERING RULE: Digits are ordered by the facade glyph positions from P01.\nCountermarks do not take a bay."}},"operator":{"role":"OPERATOR","screenTitle":"Bay Directory","visualType":"document-forensics","whatTheySee":"A directory page of Halder bay numbers and the rooms they open, and a note from the facade terminal.","taskPrompt":"Look up the number your Analyst derives. Check it against the other numbers close to it before you commit: a wrong order lands on a different room.","dataPayload":"The terminal at the foot of the facade prints a bay directory.\nQUESTION: Which room does bay number 3425 belong to?\nANSWER (ROOM NAME): [ _ _ _ _   _ _ _ ]","interactiveData":{"documentText":"HALDER INSTITUTE — BAY DIRECTORY (Admin Bldg + Science Bldg)\n\nBAY    ROOM                            DOOR\n2345   Reading Room (Library)          L-RR-D2\n3245   Lecture Hall 214                A-214-D1\n3425   East Laboratory (Science Bldg)  E-LAB-D1\n3524   Chemicals Store                 S-CHM-D1\n4325   Plant Room                      P-PLT-D3\n5432   Archive, Cabinet Hall           A-CAB-D1\n\nBAY NUMBERS ARE DOOR CODES. THEY ARE CUT, NOT ISSUED.\nThe cut numbers are the code. Nothing records who types them."}},"branchConditions":[],"coordinationChain":{"observerProduces":"Four digits as cut into the steps.","analystTransforms":"Uses the mark to put the digits in order.","operatorExecutes":"Looks the number up in the directory and files the claim."},"failurePropagation":{"wrongStep":"Taking the digits in the order they lie on the steps without checking them against the mark.","consequence":"The number lands on a different room in the directory and the claim is rejected.","recoveryGuidance":"Order the digits by where each pairing letter first appears in the mark, not by position on the steps."},"narrativeObjective":"Four brass plates are set into the steps at the foot of the entrance. The Institute put numbers where anyone could read them. Establish what the numbers are for.","roleDependencyLevel":"D2","operatorInvestigation":{"operatorOwnEvidence":"Your terminal holds: Bay Directory.","requiredDiscoveries":{"observerDiscovery":"Four digits as cut into the steps.","analystDiscovery":"Uses the mark to put the digits in order."},"operatorTaskDescription":"Which room does bay number 3425 belong to?"}}$nxj$::jsonb,
  metadata = $nxj${"time":"4m","type":"CIPHER","feeds":"P02","difficulty":2,"storyReveal":"Bay 3425 is the east laboratory. The code to its door is cut into the steps outside, where anyone could read it. A code that anyone can read cannot say who typed it.","locationClue":{"format":"Inference","clueText":"The Institute recorded people the way it recorded doors: on a schedule. A poster in the archive hall keeps one, and gives dates.","solution":"Archive Poster Examination","nextQrNode":"QR-NODE-04","explanation":"Points to the archive poster wall.","nextPhysicalLocation":"[ADMIN BUILDING] — Archive Poster Wall"},"evidenceUnlocked":{"id":"EVID-P03","state":"RECOVERED","title":"Halder Bay Directory","source":"Facade base terminal","content":"A page of the Institute’s bay directory listing rooms with their bay numbers and doors.","category":"Document","timestamp":"Act 1"},"whyTeamworkMatters":"Four digits as cut into the steps. Uses the mark to put the digits in order. Looks the number up in the directory and files the claim.","evidenceBundle":["EVID-P03"],"act":1,"mechanic":"spatial"}$nxj$::jsonb,
  answer_metadata = $nxj${"acceptedAnswer":"EAST LAB","alternatives":["EAST LABORATORY","THE EAST LAB","THE EAST LABORATORY","EAST LAB D1"],"validationMethod":"case_insensitive","redact":false,"question":"Which room does bay number 3425 belong to?","format":"ROOM NAME","fullSolution":"Plates read 3, 4, 2, 5. The bay table pairs C=3 D=4 E=5 F=2 and orders digits by first appearance of each letter in CDFDEFF: C, D, F, E gives 3,4,2,5 = 3425. The directory shows 3425 = East Laboratory, door E-LAB-D1. The note that bay numbers are door codes is the groundwork for P24b: a code proves nothing. Answer: EAST LAB."}$nxj$::jsonb
WHERE code = $nxs$P03$nxs$;
UPDATE puzzle_nodes SET
  title = $nxs$Four Sessions$nxs$,
  content = $nxj${"hints":["This is a question about a rule that nobody wrote down for you. Induce it from cases.","One session differs from the others. Look at what the Analyst reads for it and the outcome the Operator reads for it.","Most sessions closed and one did not. Count the attestations on each. The rule is the smallest number that separates closing from not closing.","A single digit. It is not the number of sessions."],"observer":{"role":"OBSERVER","screenTitle":"Poster Wall Log","visualType":"document-forensics","whatTheySee":"Four dates arranged in a vertical list on the poster.","taskPrompt":"Read the four dates exactly as printed, in the order they appear on the poster. Read every other printed line too, even if it seems to be decoration.","dataPayload":"POSTER DATES: 2021-03-15, 2021-06-22, 2021-09-08, 2021-12-01.\nThe dates are the poster’s own order. Read every other line on it."},"analyst":{"role":"ANALYST","screenTitle":"Session Attestations","visualType":"document-forensics","whatTheySee":"The 2021 NEXUS session register, which records who attested each session.","taskPrompt":"Match each session to a date your Observer reads, and report who attested it. Report attestations only; the Operator holds the outcomes.","dataPayload":"Recall the lobby seal and who attested it. Sessions are listed by number; the Observer’s dates identify them.","interactiveData":{"requiresPuzzle":"P02","recallPrompt":"Recall what the guard-desk register recorded when the lobby seal was applied.","documentText":"NEXUS SESSION REGISTER 2021 — ATTESTATIONS\n\nSESSION  DATE      ATTESTED BY\nS-1      15 MAR    R.N.  M.C.  M.S.\nS-2      22 JUN    R.N.  M.C.  M.S.\nS-3      08 SEP    R.N.  M.C.  —\nS-4      01 DEC    R.N.  M.C.  M.S.\n\nAn attestation is one custodian confirming their own copy of the event. The register records the outcome separately."}},"operator":{"role":"OPERATOR","screenTitle":"Session Outcomes","visualType":"document-forensics","whatTheySee":"The outcomes column for the same 2021 sessions, kept by a different office.","taskPrompt":"Set each session’s outcome against the attestations your Analyst reads out, and say what it takes to close a record.","dataPayload":"The outcomes are kept apart from the attestations.\nQUESTION: How many independent attestations does a NEXUS record need before it closes?\nANSWER (A NUMBER): [ _ ]","interactiveData":{"documentText":"NEXUS SESSION OUTCOMES 2021\n\nS-1  CLOSED\nS-2  CLOSED\nS-3  NOT CLOSED — re-run required\nS-4  CLOSED\n\nA closed record is final. A record that is not closed is held open and may not be cited."}},"branchConditions":[],"coordinationChain":{"observerProduces":"The four dates and any other line on the poster.","analystTransforms":"Who attested each date.","operatorExecutes":"Sets outcomes against attestations and files the rule they imply."},"failurePropagation":{"wrongStep":"Counting the sessions or the poster’s dates instead of the attestations.","consequence":"The claim is rejected: four is the number of sessions, not the number needed.","recoveryGuidance":"Compare the session that did not close with the ones that did, and count what differs."},"narrativeObjective":"A poster in the archive lists four dates. Establish what happened on them and what the sessions needed in order to count.","roleDependencyLevel":"D2","operatorInvestigation":{"operatorOwnEvidence":"Your terminal holds: Session Outcomes.","requiredDiscoveries":{"observerDiscovery":"The four dates and any other line on the poster.","analystDiscovery":"Who attested each date."},"operatorTaskDescription":"How many independent attestations does a NEXUS record need before it closes?"}}$nxj$::jsonb,
  metadata = $nxj${"time":"7m","type":"PATTERN","feeds":"P03","difficulty":3,"storyReveal":"A NEXUS record closes only when three people each confirm their own copy. When only two attested, the record stayed open. The system is a rule about agreement, not a machine.","locationClue":{"format":"Inference","clueText":"The register lists them by initial and role. In the hall of people there is a display with room for a full set, and one place on it is empty.","solution":"Hidden Third Figure Identification","nextQrNode":"QR-NODE-05","explanation":"Points to the archive figure display.","nextPhysicalLocation":"[ADMIN BUILDING] — Archive Figure Display"},"evidenceUnlocked":{"id":"EVID-P04","state":"RECOVERED","title":"NEXUS Session Register, 2021","source":"Behind the poster","content":"A register of the four 2021 NEXUS sessions with attestations and outcomes.","category":"Document","timestamp":"Act 1"},"whyTeamworkMatters":"The four dates and any other line on the poster. Who attested each date. Sets outcomes against attestations and files the rule they imply.","evidenceBundle":["EVID-P04"],"act":1,"mechanic":"pattern"}$nxj$::jsonb,
  answer_metadata = $nxj${"acceptedAnswer":"3","alternatives":["THREE","3 CUSTODIANS","THREE CUSTODIANS"],"validationMethod":"case_insensitive","redact":true,"question":"How many independent attestations does a NEXUS record need before it closes?","format":"A NUMBER","fullSolution":"Poster dates identify sessions S-1..S-4. Attestations: S-1 three (R.N., M.C., M.S.), S-2 three, S-3 two (R.N., M.C.), S-4 three. Outcomes: S-1 closed, S-2 closed, S-3 NOT CLOSED, S-4 closed. The smallest number that separates closing from not closing is 3. Answer: 3."}$nxj$::jsonb
WHERE code = $nxs$P04$nxs$;
UPDATE puzzle_nodes SET
  title = $nxs$The Empty Frame$nxs$,
  content = $nxj${"hints":["A letter on an empty frame can stand for a name or a thing. The schedule tells you which kind this display uses.","The schedule says what the frames are etched with. The roster lists the roles and the one person who is not in them.","Frames one and two are etched with the initial of their role. Apply the same rule to frame three and list the roles that begin with the letter.","A role from the roster, not a surname. It is not the designer’s role."],"observer":{"role":"OBSERVER","screenTitle":"Figure Display Log","visualType":"observation","whatTheySee":"A display with three frames. The third frame is empty but has an etched initial: V.","taskPrompt":"Describe the two photographs as precisely as you can, then the third frame. Report the etched letter exactly.","dataPayload":"DISPLAY: Two photos visible. Third photo frame is empty but has an etched initial: V.\nThe frames are in a row, left to right. Say whether the two photographs carry anything beneath them."},"analyst":{"role":"ANALYST","screenTitle":"Custodian Roster","visualType":"document-forensics","whatTheySee":"The 2021 roster of NEXUS custodians and the one person who stands outside them.","taskPrompt":"Read the roster and report who holds what, in the roles’ own words. Say who is listed outside the custodians, and what is said of them.","dataPayload":"The initials on this roster are the ones on the session register. Recall them.","interactiveData":{"requiresPuzzle":"P04","recallPrompt":"Recall the three sets of initials that attested the sessions that closed.","documentText":"NEXUS — ROSTER OF CUSTODIANS, 2021 ISSUE\n\nROLE            INITIALS   HOLDS\nOBSERVATION     R.N.       the copy of what was seen (photographic)\nANALYSIS        M.C.       the copy of what was measured (ledgers, tapes)\nVERIFICATION    M.S.       the copy of what was filed (boxes, custody)\n\nNOT A CUSTODIAN\nDESIGNER        L.V.       attests nothing. Holds no copy. Designed the quorum."}},"operator":{"role":"OPERATOR","screenTitle":"Display Schedule","visualType":"document-forensics","whatTheySee":"The display schedule for the figure display and the 2021 staff directory.","taskPrompt":"Set the display schedule against the roster your Analyst reads. Test every name that could begin with the letter before you accept one.","dataPayload":"Frames are etched by whatever the schedule says is etched. Check the directory for every name or role that fits.\nQUESTION: What does the letter in the empty third frame stand for?\nANSWER (ONE WORD, a role): [ _ _ _ _ _ _ _ _ _ _ _ _ ]","interactiveData":{"documentText":"DISPLAY SCHEDULE — CUSTODIAN WALL (2021)\n\nFrame 1: OBSERVATION   — portrait, etched initial of the role\nFrame 2: ANALYSIS      — portrait, etched initial of the role\nFrame 3: portrait withdrawn Dec 2021; frame left in place, initial of the role retained\n\nSTAFF DIRECTORY 2021 (extract)\nCARTER, M. — Systems Theory\nRAHAL, N. — Facilities\nSELIM, M. — Archivist\nVALE, A. — Directorate liaison\nVEY, L. — Project Lead, Designer"}},"branchConditions":[],"coordinationChain":{"observerProduces":"The two photographs, the empty frame and its etched letter.","analystTransforms":"Turns the roster into roles, copies and the person outside the three.","operatorExecutes":"Sets the schedule against the roster and files what the letter stands for."},"failurePropagation":{"wrongStep":"Reading the letter as the initial of the most prominent person in the case.","consequence":"The claim is rejected: the schedule says what is etched, and it is a role.","recoveryGuidance":"The frames carry the initial of the role. List the roles on the roster and see which begins with the letter."},"narrativeObjective":"A display has room for three people. Two frames hold photographs; the third is empty and carries one letter. Establish what the letter stands for.","roleDependencyLevel":"D2","operatorInvestigation":{"operatorOwnEvidence":"Your terminal holds: Display Schedule.","requiredDiscoveries":{"observerDiscovery":"The two photographs, the empty frame and its etched letter.","analystDiscovery":"Turns the roster into roles, copies and the person outside the three."},"operatorTaskDescription":"What does the letter in the empty third frame stand for?"}}$nxj$::jsonb,
  metadata = $nxj${"time":"6m","type":"DEDUCTION","feeds":"P04","difficulty":3,"storyReveal":"The third seat belongs to Verification, not to Vey. She designed the quorum and stands outside it. Whoever binds a record as its designer is not one of the three who make it close.","locationClue":{"format":"Inference","clueText":"Five findings now agree about one evening. A terminal in the archive will only open to a unit that can say what those five add up to.","solution":"Archive Hidden Compartment","nextQrNode":"QR-NODE-06","explanation":"Points to the hidden compartment behind the third frame.","nextPhysicalLocation":"[ADMIN BUILDING] — Archive Hidden Compartment"},"evidenceUnlocked":{"id":"EVID-P05","state":"RECOVERED","title":"Custodian Roster and Display Schedule, 2021","source":"Behind the figure display","content":"The 2021 roster of NEXUS custodians with the display schedule for the custodian wall.","category":"Document","timestamp":"Act 1"},"whyTeamworkMatters":"The two photographs, the empty frame and its etched letter. Turns the roster into roles, copies and the person outside the three. Sets the schedule against the roster and files what the letter stands for.","evidenceBundle":["EVID-P05"],"act":1,"mechanic":"identity"}$nxj$::jsonb,
  answer_metadata = $nxj${"acceptedAnswer":"VERIFICATION","alternatives":["VERIFIER","THE VERIFICATION CUSTODIAN","VERIFICATION CUSTODIAN","VERIFICATION COPY"],"validationMethod":"case_insensitive","redact":false,"question":"What does the letter in the empty third frame stand for?","format":"ONE WORD (a role)","fullSolution":"Frame 3 is etched V, the schedule says frames carry the initial of the role. Roles: Observation, Analysis, Verification. Only Verification begins with V; the designer role is D and is expressly outside the custodians. Directory names beginning with V (Vale, Vey) are not roles on the wall. Answer: VERIFICATION."}$nxj$::jsonb
WHERE code = $nxs$P05$nxs$;
UPDATE puzzle_nodes SET
  title = $nxs$Seal Register$nxs$,
  content = $nxj${"hints":["This is a synthesis: you are asked to name an event by matching conditions. Your findings are the conditions.","The Analyst holds definitions; the Operator holds what the register recorded at the held moment.","Count who attested and how close together, and note whether anyone outside the three bound the entry. Match every condition to a definition.","One word, one of the four event types. It is not one that changes an existing record."],"observer":{"role":"OBSERVER","screenTitle":"Findings Terminal","visualType":"meta","whatTheySee":"A terminal showing the five findings your unit has filed.","taskPrompt":"Read the five findings aloud in the order shown. Say which of them concern a person and which concern a place or a time.","dataPayload":"STAGE 1 FINDINGS — as filed by this unit.\nThey are listed in the order they were closed.","interactiveData":{"answers":["HALDER","21:47","EAST LAB","3","VERIFICATION"],"hint":"Five findings. One evening."}},"analyst":{"role":"ANALYST","screenTitle":"Event Types","visualType":"document-forensics","whatTheySee":"The register of NEXUS event types and the conditions for each.","taskPrompt":"Read out the definition of each event type. Say which ones need custodians and which do not.","dataPayload":"Recall the rule for closing a record and who the three custodians are.","interactiveData":{"requiresPuzzle":"P05","recallPrompt":"Recall who the three custodians are and what the empty frame stood for.","documentText":"NEXUS EVENT TYPES\n\nSYNC   a custodian refreshes their own copy. One custodian.\nVOID   a custodian withdraws their copy. One custodian.\nAMEND  a record is corrected. Three custodians, each in writing.\nSEAL   a record is closed. Three custodians attest within one minute; the designer binds it.\n\nEvery event is entered against a reference of the form SQ-yy-nnn."}},"operator":{"role":"OPERATOR","screenTitle":"Bulletin and Register","visualType":"contradiction-hunt","whatTheySee":"The Bureau’s bulletin of 18 October beside the guard-desk register entries.","taskPrompt":"Read the bulletin against the register. Report which statements can both be true and which cannot. Then state which event type matches what the register shows.","dataPayload":"Two documents about the same evening. The register and the bulletin are both genuine.\nQUESTION: What was applied to the record at the moment the lobby clock is holding?\nANSWER (ONE WORD — an event type): [ _ _ _ _ ]","interactiveData":{"entries":[{"source":"BULLETIN MP-24-018 · 18 OCT 09:40","text":"Dr. L. Vey left the Admin Building at 17:30 on 17 October. She has not been seen since.","flag":false},{"source":"GUARD DESK · 17 OCT 17:28","text":"OUT L.V. (badge, main entrance).","flag":false},{"source":"GUARD DESK · 17 OCT 21:44","text":"QUORUM ATTEST begins (SQ-24-001).","flag":false},{"source":"GUARD DESK · 17 OCT 21:47","text":"SQ-24-001 applied. Tri-attest. Register notes the designer’s initials against the entry.","flag":false},{"source":"GUARD DESK · 17 OCT 22:45","text":"Facilities, lobby clock (LC-01).","flag":false}]}},"branchConditions":[],"coordinationChain":{"observerProduces":"The five filed findings, read aloud, in order.","analystTransforms":"The definitions of the event types and what each needs.","operatorExecutes":"Sets the bulletin against the register and names the event that matches."},"failurePropagation":{"wrongStep":"Naming an event that needs fewer than three custodians, or one that changes a record rather than closing it.","consequence":"The claim is rejected: the register shows three attestations inside a minute and a designer’s binding.","recoveryGuidance":"Match the register entry’s conditions to the definitions, not to the name of the reference."},"narrativeObjective":"Five findings have been filed. Put them together: what kind of event happened in the Admin Building after the bulletin says Dr. Vey left it?","roleDependencyLevel":"D4","operatorInvestigation":{"operatorOwnEvidence":"Your terminal holds: Bulletin and Register.","requiredDiscoveries":{"observerDiscovery":"The five filed findings, read aloud, in order.","analystDiscovery":"The definitions of the event types and what each needs."},"operatorTaskDescription":"What was applied to the record at the moment the lobby clock is holding?"}}$nxj$::jsonb,
  metadata = $nxj${"time":"12m","type":"META","feeds":"P01 P02 P03 P04 P05","difficulty":4,"storyReveal":"At 21:47 three custodians closed a record, and the designer bound it. The bulletin says she left at 17:30 and has not been seen since. The register disagrees with half of that sentence.","locationClue":{"format":"Inference","clueText":"Whoever binds a record after leaving the building prepared for it before she went. Preparation leaves paper, and the building’s library keeps a ledger.","solution":"Library Basement East Stairwell","nextQrNode":"QR-NODE-06","explanation":"Points to the library basement.","nextPhysicalLocation":"[LIBRARY] — Stack Reference Desk"},"evidenceUnlocked":{"id":"EVID-M01","state":"RECOVERED","title":"Seal Slip SQ-24-001","source":"Central archive terminal (print)","content":"The seal slip entered against SQ-24-001 on 17 October 2024.","category":"Document","timestamp":"Act 1"},"whyTeamworkMatters":"The five filed findings, read aloud, in order. The definitions of the event types and what each needs. Sets the bulletin against the register and names the event that matches.","evidenceBundle":["EVID-M01","EVID-M01-B"],"act":1,"mechanic":"synthesis"}$nxj$::jsonb,
  answer_metadata = $nxj${"acceptedAnswer":"SEAL","alternatives":["THE SEAL","A SEAL","QUORUM SEAL","SEAL APPLIED"],"validationMethod":"case_insensitive","redact":false,"question":"What was applied to the record at the moment the lobby clock is holding?","format":"ONE WORD (an event type)","fullSolution":"Register entry SQ-24-001 at 21:47 shows three attestations within a minute (21:44–21:47) and a designer’s binding. Event types: SYNC and VOID need one custodian; AMEND needs three in writing and changes a record; SEAL needs three attesting within one minute with the designer binding. Answer: SEAL. Side finding: the designer’s initials are against a 21:47 entry in a building the bulletin says she left at 17:30."}$nxj$::jsonb
