INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P01$nxs$, $nxs$Register of Institutional Marks, 1974$nxs$, $nxs$A scanned register of marks and the offices that held them, with an addendum reference.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"REGISTER OF INSTITUTIONAL MARKS, 1974 ISSUE. CDFDEFF Halder Institute for Continuity Studies (Admin Bldg, main and east wing). DBFFECD Estates Office (Annex B). CEEDFDC Printing and Stores. FDCEFDE Plant and Heating. BDFCEED Bureau of Continuity Records (issued 1998, retention desk). CDFDEEF University Estates, consolidated (issued 1998). Countermarks: see Addendum A (restricted). Stamp: DISSOLVED 1998 against the Halder row.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Archive alcove, lobby","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"1974-06-03","captured_at":"1974-06-03","condition":"NORMAL","image_url":"/evidence/case/ab2661c13df05b.jpg","thumb_url":"/evidence/case/ab2661c13df05b-t.jpg","relationships":[{"to":"EVID-P22","kind":"EXPLAINS","note":"The register refers to a restricted addendum of countermarks."}]}$nxj$::jsonb, $nxj${"node":"P01","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Archive alcove, lobby"}$nxj$::jsonb)
