INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P02$nxs$, $nxs$Lobby Clock Maintenance Card LC-01$nxs$, $nxs$Facilities maintenance card for the lobby clock with a single entry for 17 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"LOBBY CLOCK, MAINTENANCE CARD LC-01. 17 OCT 2024 22:45. Face set by hand to the time entered against SQ-24-001 in the guard-desk register (evening entry). Movement isolated at the gear train. Not to be reset or restarted without a Facilities ticket. N. Rahal, Facilities.","state":"UNREVIEWED","artifact_type":"NOTE","source":"Behind the lobby clock face","custodian":"Facilities","provenance":"Original record; first-hand","date":"2024-10-17 22:45","captured_at":"2024-10-17 22:45","condition":"NORMAL","image_url":"/evidence/case/28c81ba94820c0.jpg","thumb_url":"/evidence/case/28c81ba94820c0-t.jpg","relationships":[{"to":"EVID-P02-B","kind":"CORROBORATES","note":"The register entry the card cites."}]}$nxj$::jsonb, $nxj${"node":"P02","reliability":"primary","custodian":"Facilities","source":"Behind the lobby clock face"}$nxj$::jsonb)
