INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P02-B$nxs$, $nxs$Guard-Desk Register GD-241017$nxs$, $nxs$The guard-desk register page for 17 October 2024, Admin Building.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"GUARD DESK, ADMIN BUILDING, 17 OCT 2024. 08:02 IN staff (14). 12:30 contractor lift service. 17:28 OUT L.V. (badge, main entrance). 18:15 night cleaners IN. 21:44 QUORUM ATTEST begins (SQ-24-001). 21:47 SQ-24-001 APPLIED tri-attest. 22:45 Facilities, lobby clock (LC-01). 23:10 OUT Facilities. No further main-entrance badge events recorded for the night.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Main entrance guard desk","custodian":"Estates security","provenance":"Original record; first-hand","date":"2024-10-17","captured_at":"2024-10-17","condition":"NORMAL","image_url":"/evidence/case/f677ca8959ed2e.jpg","thumb_url":"/evidence/case/f677ca8959ed2e-t.jpg","relationships":[{"to":"EVID-M01-B","kind":"CONTRADICTS","note":"The bulletin’s account of her movements stops at 17:30."}]}$nxj$::jsonb, $nxj${"node":"P02","reliability":"primary","custodian":"Estates security","source":"Main entrance guard desk"}$nxj$::jsonb)
