INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P03$nxs$, $nxs$Halder Bay Directory$nxs$, $nxs$A page of the Institute’s bay directory listing rooms with their bay numbers and doors.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"HALDER INSTITUTE BAY DIRECTORY (Admin Bldg and Science Bldg). 2345 Reading Room (Library) L-RR-D2. 3245 Lecture Hall 214 A-214-D1. 3425 East Laboratory (Science Bldg) E-LAB-D1. 3524 Chemicals Store S-CHM-D1. 4325 Plant Room P-PLT-D3. 5432 Archive, Cabinet Hall A-CAB-D1. Bay numbers are door codes. They are cut, not issued. Nothing records who types them.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Facade base terminal","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"1974-06-03","captured_at":"1974-06-03","condition":"NORMAL","image_url":"/evidence/case/5f63c8920219c8.jpg","thumb_url":"/evidence/case/5f63c8920219c8-t.jpg","relationships":[{"to":"EVID-P01","kind":"DERIVES","note":"Bay numbers derive from the Halder mark."}]}$nxj$::jsonb, $nxj${"node":"P03","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Facade base terminal"}$nxj$::jsonb)
