INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P04$nxs$, $nxs$NEXUS Session Register, 2021$nxs$, $nxs$A register of the four 2021 NEXUS sessions with attestations and outcomes.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"NEXUS SESSION REGISTER 2021. S-1 15 March attested R.N. M.C. M.S. CLOSED. S-2 22 June R.N. M.C. M.S. CLOSED. S-3 8 September R.N. M.C. (none for third) NOT CLOSED, re-run required. S-4 1 December R.N. M.C. M.S. CLOSED.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Behind the poster","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2021-12-01","captured_at":"2021-12-01","condition":"NORMAL","image_url":"/evidence/case/da53fef89f6e51.jpg","thumb_url":"/evidence/case/da53fef89f6e51-t.jpg","relationships":[{"to":"EVID-P05","kind":"EXPLAINS","note":"The initials on the register are the custodians on the roster."}]}$nxj$::jsonb, $nxj${"node":"P04","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Behind the poster"}$nxj$::jsonb)
