INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P05$nxs$, $nxs$Custodian Roster and Display Schedule, 2021$nxs$, $nxs$The 2021 roster of NEXUS custodians with the display schedule for the custodian wall.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"NEXUS ROSTER OF CUSTODIANS, 2021. OBSERVATION R.N. holds the copy of what was seen. ANALYSIS M.C. holds the copy of what was measured. VERIFICATION M.S. holds the copy of what was filed. Not a custodian: DESIGNER L.V., attests nothing, holds no copy, designed the quorum. Display schedule: frames carry the initial of the role; the third portrait was withdrawn December 2021 and the frame left in place. Staff directory: Carter M. Systems Theory; Rahal N. Facilities; Selim M. Archivist; Vale A. Directorate liaison; Vey L. Project Lead, Designer.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Behind the figure display","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2021-12-04","captured_at":"2021-12-04","condition":"NORMAL","image_url":"/evidence/case/953c6dfe0497ce.jpg","thumb_url":"/evidence/case/953c6dfe0497ce-t.jpg","relationships":[{"to":"EVID-P04","kind":"EXPLAINS","note":"R.N., M.C., M.S. on the session register are the custodians here."}]}$nxj$::jsonb, $nxj${"node":"P05","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Behind the figure display"}$nxj$::jsonb)
