INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-M01$nxs$, $nxs$Seal Slip SQ-24-001$nxs$, $nxs$The seal slip entered against SQ-24-001 on 17 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"NEXUS SEAL SLIP SQ-24-001. Applied 17 OCT 2024 21:47. Attested: R.N. (21:44), M.C. (21:45), M.S. (21:47). Bound (designer): L.V. Room: not entered. Checks 1 to 7: ticked 1 2 3 4, 5 blank, 6 7 ticked.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Central archive terminal (print)","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2024-10-17 21:47","captured_at":"2024-10-17 21:47","condition":"NORMAL","image_url":"/evidence/case/58ddf0c21dfd8a.jpg","thumb_url":"/evidence/case/58ddf0c21dfd8a-t.jpg","relationships":[{"to":"EVID-M01-B","kind":"CONTRADICTS","note":"The bulletin says she was not seen after 17:30."},{"to":"EVID-P02-B","kind":"CORROBORATES","note":"The guard-desk register logs the same seal at 21:47."}]}$nxj$::jsonb, $nxj${"node":"M01","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Central archive terminal (print)"}$nxj$::jsonb)
