INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-M01-B$nxs$, $nxs$Bureau Bulletin MP-24-018$nxs$, $nxs$Missing-person bulletin issued by the Bureau on 18 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"BUREAU BULLETIN MP-24-018. 18 OCT 2024 09:40. Dr. L. Vey left the Admin Building at 17:30 on 17 October. She has not been seen since. Any information to the Oversight Officer, A. Vale. Issued under the authority of the Directorate.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Bureau notice board","custodian":"Bureau of Continuity Records","provenance":"Official statement; not independently checked","date":"2024-10-18 09:40","captured_at":"2024-10-18 09:40","condition":"NORMAL","image_url":"/evidence/case/1edae427c1f829.jpg","thumb_url":"/evidence/case/1edae427c1f829-t.jpg","relationships":[{"to":"EVID-M01","kind":"CONTRADICTS","note":"A seal bound with her initials at 21:47."}]}$nxj$::jsonb, $nxj${"node":"M01","reliability":"secondary","custodian":"Bureau of Continuity Records","source":"Bureau notice board"}$nxj$::jsonb)
