INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P06$nxs$, $nxs$Reference Desk Lending Ledger, Entry #06$nxs$, $nxs$The library’s lending ledger page for restricted-case item 06, with the loan history of the item.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"UNIVERSITY LIBRARY, REFERENCE DESK. LENDING LEDGER, RESTRICTED CASES (R2). ENTRY #06. Loan history. OUT 14/02/2022 Estates office, DUE 21/02/2022, IN 18/02/2022. OUT 03/05/2023 Facilities, DUE 10/05/2023, IN 08/05/2023. OUT 17/10/2024 L.V., DUE blank, IN blank. Initials L.V. handwritten in the borrower column. The item is identified by number only.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Library reference desk","custodian":"University Library","provenance":"Original record; first-hand","date":"2024-10-17","captured_at":"2024-10-17","condition":"NORMAL","image_url":"/evidence/case/62a31a2c02f57a.jpg","thumb_url":"/evidence/case/62a31a2c02f57a-t.jpg","relationships":[{"to":"EVID-M01","kind":"PRECEDES","note":"The same initials bind the seal of 21:47."},{"to":"EVID-P07","kind":"CORROBORATES","note":"The library server holds its own record of the loan."}]}$nxj$::jsonb, $nxj${"node":"P06","reliability":"primary","custodian":"University Library","source":"Library reference desk"}$nxj$::jsonb)
