INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P07$nxs$, $nxs$Library Circulation Extract, 17 Oct 2024$nxs$, $nxs$The library server’s circulation extract for 17 October 2024 with slip, item, card and stamped times.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"LIBSRV-01 CIRCULATION, 17 OCT 2024. SLIP ITEM CARD OUT IN. 44709 #11 0233 13:08:07 13:41:50. 44714 #07 0412 14:30:44 15:12:03. 44716 #02 0233 17:20:31 18:02:09. 44721 #06 0617 21:22:14, no IN. Last slip issued: 44721. Footer: libsrv01 | time source: local rtc | ntp: unsynchronised.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Library basement server rack","custodian":"University Library","provenance":"Official statement; not independently checked","date":"2024-10-17","captured_at":"2024-10-17","condition":"NORMAL","image_url":"/evidence/case/9a1e042c14a481.jpg","thumb_url":"/evidence/case/9a1e042c14a481-t.jpg","relationships":[{"to":"EVID-P06","kind":"CORROBORATES","note":"The paper ledger records the same loan without a time."},{"to":"EVID-P02-B","kind":"CONTRADICTS","note":"The guard register logs L.V. out at 17:28, before this stamp."}]}$nxj$::jsonb, $nxj${"node":"P07","reliability":"secondary","custodian":"University Library","source":"Library basement server rack"}$nxj$::jsonb)
