INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P08$nxs$, $nxs$A-201-G Issue 03, Route Legend$nxs$, $nxs$The notes sheet of the Admin Building ground-floor plan, issue 03, with the legend of route classes.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"HALDER INSTITUTE, DRAWING OFFICE. A-201-G ISSUE 03, NOTES SHEET 1, ROUTE LEGEND. ALPHA public corridors, black, LINE: one E-W run per level, no branching. BETA stairs, green, SPURS: single flights, each serving two levels. GAMMA lifts, red, SHAFTS: two, independent. DELTA service routes, blue, NETWORK: branching, nine junctions, links plant, ground floor and lower ground. A junction is a point where three or more routes meet. Sheet date 14 MAR 1995.","state":"UNREVIEWED","artifact_type":"MAP","source":"Archive cabinet, drawing set A-201-G","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"1995-03-14","captured_at":"1995-03-14","condition":"NORMAL","image_url":"/evidence/case/eb7a0e9f2d9b68.jpg","thumb_url":"/evidence/case/eb7a0e9f2d9b68-t.jpg","relationships":[{"to":"EVID-P06","kind":"DERIVES","note":"The legend belongs to the drawing set she signed out."},{"to":"EVID-P10","kind":"PRECEDES","note":"The colour legend assigns door categories to the same classes."}]}$nxj$::jsonb, $nxj${"node":"P08","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Archive cabinet, drawing set A-201-G"}$nxj$::jsonb)
