INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P09$nxs$, $nxs$Master Clock Output Channels$nxs$, $nxs$A printout of the master clock’s output channels with each sink’s offset from building time and its last sync.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"MASTER CLOCK, OUTPUT CHANNELS. Printed 18 OCT 2024 07:10, Plant office. Master = building time. OFFSET = sink minus master. I LOBBY TOWER FACE, hand-set, HELD 17 OCT 22:45 (LC-01). II GUARD DESK +00:00:00, last sync 18 OCT 03:00, OK. III ACCESS CONTROL +00:00:00, 18 OCT 03:00, OK. IV CAMERA BANKS +00:00:00, 18 OCT 03:00, OK. V DOOR SENSORS +00:00:00, 18 OCT 03:00, OK. VI BUILDING CONTROLS +00:00:00, 18 OCT 03:00, OK. VII LIB-SRV +04:00:00, last sync 14 SEP 2021, FREE-RUN. VIII TOWER BELL +00:00:00, last sync 18 OCT 03:00, OK.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Clock room","custodian":"Estates, Plant office","provenance":"Original record; first-hand","date":"2024-10-18 07:10","captured_at":"2024-10-18 07:10","condition":"NORMAL","image_url":"/evidence/case/0c0fe4eaa6e356.jpg","thumb_url":"/evidence/case/0c0fe4eaa6e356-t.jpg","relationships":[{"to":"EVID-P07","kind":"CONTRADICTS","note":"Corrects the stamp on slip 44721 by the host’s offset."},{"to":"EVID-P02","kind":"EXPLAINS","note":"Row I records the hand-set lobby face and its hold."}]}$nxj$::jsonb, $nxj${"node":"P09","reliability":"primary","custodian":"Estates, Plant office","source":"Clock room"}$nxj$::jsonb)
