INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P10$nxs$, $nxs$Estates Key Schedule, Admin Building$nxs$, $nxs$The 2021 key schedule for the Admin Building, by door category, with lock type, reader and keyholders.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"ESTATES, KEY SCHEDULE, ADMIN BUILDING (2021 re-key). PA public: latch, card reader, reader YES, card for all staff. RS restricted staff: card reader and PIN, YES. HS heavy service: card reader and cut key, YES, card plus key group KP (Estates). LS light service: mortice lock, cut key, reader NONE, key group KM = maintenance key, Facilities, four numbered sets. FE fire exit: push-bar, alarm, reader NONE. Remark: doors with no reader are not on the access-control system and are not logged.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Blue-marked door, with the blueprint","custodian":"Estates Office","provenance":"Original record; first-hand","date":"2021-06-14","captured_at":"2021-06-14","condition":"NORMAL","image_url":"/evidence/case/0d5c0c02b7551b.jpg","thumb_url":"/evidence/case/0d5c0c02b7551b-t.jpg","relationships":[{"to":"EVID-P08","kind":"DERIVES","note":"The blue service route is the light-service category."},{"to":"EVID-P11","kind":"PRECEDES","note":"The door schedule lists the openings this schedule governs."}]}$nxj$::jsonb, $nxj${"node":"P10","reliability":"primary","custodian":"Estates Office","source":"Blue-marked door, with the blueprint"}$nxj$::jsonb)
