INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P11$nxs$, $nxs$A-201-G Issue 03, Door Schedule and West Spine$nxs$, $nxs$A door schedule extract for the ground-floor plan, issue 03, with a note of the west spine gridlines.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"A-201-G ISSUE 03, DOOR SCHEDULE (extract). A-214-D1 hall door, GF, ALPHA, W4. A-CAB-D1 hall door, GF, ALPHA, E3. A-031-ARC archway, GF, ALPHA, E1. S01-TUN archway, GF, DELTA, W3. S06-TUN archway, LG, DELTA, P2. P-PLT-D3 plant door, LG, no route, P3. Grid: W west spine, E east wing, P plant corridor. West spine from the lobby end: W1 lobby end, W2 stair, W3 recess (service-route ring), W4 foyer door A-214-D1, Hall 214.","state":"UNREVIEWED","artifact_type":"MAP","source":"Wall with the glowing symbol, from drawing set A-201-G","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"1995-03-14","captured_at":"1995-03-14","condition":"NORMAL","image_url":"/evidence/case/116d68d231af83.jpg","thumb_url":"/evidence/case/116d68d231af83-t.jpg","relationships":[{"to":"EVID-P10","kind":"CORROBORATES","note":"The route class is the service route whose doors have no reader."},{"to":"EVID-P12","kind":"PRECEDES","note":"The lecture hall at W4 is the next room on the spine."}]}$nxj$::jsonb, $nxj${"node":"P11","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Wall with the glowing symbol, from drawing set A-201-G"}$nxj$::jsonb)
