INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P12$nxs$, $nxs$Hall 214 Block, Issues 02 and 03 Compared$nxs$, $nxs$Dimensions and room schedules for the Hall 214 block taken from issues 02 and 03 of the ground-floor plan, side by side.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"A-201-G, HALL 214 BLOCK, ISSUES COMPARED. Issue 02 (Aug 1991) and issue 03 (Mar 1995). Block, gridline to gridline: 13.0 m and 13.0 m. Walls, front plus rear: 0.6 m and 0.6 m. Hall 214 width: 9.6 m and 9.6 m. Hall 214 depth (dimension): 12.4 m and 8.1 m. Room schedule, issue 02: 214 hall (panel P-214), 214A AV store (P-214A), C214-X rear room, entered from the hall only (panel P-214X). Room schedule, issue 03: 214 hall (P-214), 214A AV store (P-214A). Issue 03 draws the area behind the hall’s rear wall as solid fill, unlabelled. Issue 02 draws a screen wall across the hall at 8.1 m.","state":"UNREVIEWED","artifact_type":"MAP","source":"Drawing set A-201-G (library R2-06), Hall 214 sheets","custodian":"Bureau of Continuity Records","provenance":"Derived from other records","date":"2024-10-17","captured_at":"2024-10-17","condition":"NORMAL","image_url":"/evidence/case/991772f4feb981.jpg","thumb_url":"/evidence/case/991772f4feb981-t.jpg","relationships":[{"to":"EVID-P12-B","kind":"CORROBORATES","note":"The work order wires the switch to the same panel, P-214X."},{"to":"EVID-P06","kind":"DERIVES","note":"Both issues come from the set she signed out."}]}$nxj$::jsonb, $nxj${"node":"P12","reliability":"derived","custodian":"Bureau of Continuity Records","source":"Drawing set A-201-G (library R2-06), Hall 214 sheets"}$nxj$::jsonb)
