INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P12-B$nxs$, $nxs$Facilities Work Order FWO-21-0431 and Hall 214 Booking$nxs$, $nxs$A 2021 facilities work order for Hall 214 and the hall’s booking register line for 17 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"FACILITIES WORK ORDER FWO-21-0431. HALL 214. Raised 03 FEB 2021, completed 19 MAR 2021. Estates ref EO/21/118. Requested: L. Vey. 1 Replace armrest hinges, rows A to C. 2 Re-lamp stage lights. 3 Fit momentary switch (normally open) under the armrest, row B seat 7. Cable via riser R2 to panel P-214X. 4 Panel P-214X: relay K1 drives the actuator of the concealed pivot panel in the rear screen wall of the hall. 5 Label panel. BOOKING REGISTER, HALL 214: 17 OCT 2024, 19:00-22:00, booked 11 OCT by L.V. Title: Continuity lecture. Attendees recorded: none.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Lecture Hall 214, under seat B7","custodian":"Estates, Facilities","provenance":"Original record; first-hand","date":"2021-03-19","captured_at":"2021-03-19","condition":"NORMAL","image_url":"/evidence/case/ee044a4ca4dc79.jpg","thumb_url":"/evidence/case/ee044a4ca4dc79-t.jpg","relationships":[{"to":"EVID-P12","kind":"CORROBORATES","note":"The panel named here is the panel of the rear room the plans list."},{"to":"EVID-M01","kind":"PRECEDES","note":"The booking window contains the seal at 21:47."}]}$nxj$::jsonb, $nxj${"node":"P12","reliability":"primary","custodian":"Estates, Facilities","source":"Lecture Hall 214, under seat B7"}$nxj$::jsonb)
