INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P13$nxs$, $nxs$East Laboratory Run Register$nxs$, $nxs$The east laboratory’s run register with two protocol series, and the Research Office protocol index.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"EAST LABORATORY RUN REGISTER. Science Building Research Office. Series are filed under the protocol code and numbered separately. CAL-1 11 NOV 1991 C214-X levels only. CAL-2 02 SEP 1993 C214-X levels only. MTP-1 13 OCT 1994 C214-X not entered. MTP-2 15 MAR 2021 E-LAB-D1 CLOSED. MTP-3 22 JUN 2021 E-LAB-D1 CLOSED. MTP-4 08 SEP 2021 E-LAB-D1 NOT CLOSED. MTP-5 01 DEC 2021 E-LAB-D1 CLOSED. MTP-6 17 OCT 2024 C214-X SQ-24-001. Note: MTP-1 transcribed from the Hall 214 annex log when this register was opened (2021). Protocol index: CAL recorder and camera calibration; MTP Memory Transfer Protocol; both registers kept at E-LAB-D1.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Science Building, research laboratory (east)","custodian":"Science Building Research Office","provenance":"Original record; first-hand","date":"2024-10-17","captured_at":"2024-10-17","condition":"NORMAL","image_url":"/evidence/case/42375aa4727652.jpg","thumb_url":"/evidence/case/42375aa4727652-t.jpg","relationships":[{"to":"EVID-P03","kind":"CORROBORATES","note":"Bay 3425 is the east laboratory whose register this is."},{"to":"EVID-P12","kind":"CORROBORATES","note":"Issue 02 of the plan draws the annex that the earliest rows name."}]}$nxj$::jsonb, $nxj${"node":"P13","reliability":"primary","custodian":"Science Building Research Office","source":"Science Building, research laboratory (east)"}$nxj$::jsonb)
