INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-M02$nxs$, $nxs$Case Conference Note: Re-entry$nxs$, $nxs$The unit’s note of which routes into the building would have left a record of Dr. Vey on the evening of 17 October.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"CASE CONFERENCE NOTE CC-02. Question: how could L.V. re-enter the Admin Building without a badge record? Routes and what each would have recorded. Main entrance: guard desk plus card reader; 17:28 OUT, no IN. ALPHA corridors: card reader; no reads for L.V. after 17:28. BETA stairs: card reader; none. GAMMA lifts: car reader; none. DELTA service network, below-grade service tunnels: maintenance key, no reader, nothing could have been recorded. Library slip 44721 (21:22) discounted: library server runs +04:00, true time 17:22. Open: the time of entry, and whether Route Delta was in fact used.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Memory lab terminal (print)","custodian":"Investigating unit","provenance":"Derived from other records","date":"2026-10-07","captured_at":"2026-10-07","condition":"NORMAL","image_url":"/evidence/case/e0ce711ad196ea.jpg","thumb_url":"/evidence/case/e0ce711ad196ea-t.jpg","relationships":[{"to":"EVID-P09","kind":"EXPLAINS","note":"The 21:22 library stamp cannot place her at a door: that server runs four hours ahead."},{"to":"EVID-P10","kind":"DERIVES","note":"Blue doors keep no reader."},{"to":"EVID-P11","kind":"DERIVES","note":"S01-TUN is the head of the Delta service network."}]}$nxj$::jsonb, $nxj${"node":"M02","reliability":"derived","custodian":"Investigating unit","source":"Memory lab terminal (print)"}$nxj$::jsonb)
