VALUES ($nxs$EVID-P06B$nxs$, $nxs$Lab Symbol Key$nxs$, $nxs$A card from the laboratory symbol drawer keying seven symbols to seven names.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"LAB SYMBOL KEY. ⟁ Origin (what was seen). ⧉ Connection (what was measured), marked with a star. ⬡ Structure (what was filed). ⧫ Memory. ⌬ Choice. ⍟ Truth. ⎔ Finality. Symbols are listed in this order. Pencil: second glyph starred.","state":"UNREVIEWED","artifact_type":"NOTE","source":"Lab symbol drawer, east laboratory","custodian":"Science Building Research Office","provenance":"Original record; first-hand","date":"2021-03-15","captured_at":"2021-03-15","condition":"NORMAL","image_url":"/evidence/case/c5092952b76318.jpg","thumb_url":"/evidence/case/c5092952b76318-t.jpg","relationships":[{"to":"EVID-P07B","kind":"EXPLAINS","note":"The copy symbols are read off this key."}]}$nxj$::jsonb, $nxj${"node":"P06b","reliability":"primary","custodian":"Science Building Research Office","source":"Lab symbol drawer, east laboratory"}$nxj$::jsonb)
