INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P06B-B$nxs$, $nxs$UPS Controller Event Log, Science Building$nxs$, $nxs$Extract of the UPS controller event log for two units, night of 17 to 18 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"SCIENCE BUILDING UPS CONTROLLER EVENT LOG (extract). Controller clock: building time (master clock, no offset). UNIT UPS-SB-03: 17 OCT 22:10:41 C3 TRIP overcurrent, auto-reset 22:10:44. 18 OCT 02:40:12 ALL MAINS DIP 0.4 s, battery held, no circuit lost. 18 OCT 04:15:03 C7 OFF ticket logged, number in detail file. 18 OCT 05:15:20 C7 ON restored. UNIT UPS-SB-04: 17 OCT 23:41:50 C7 OFF surge protection. 17 OCT 23:41:58 C7 ON restored.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Science Building plant controller (print)","custodian":"Estates Facilities","provenance":"Original record; first-hand","date":"2024-10-18","captured_at":"2024-10-18","condition":"NORMAL","image_url":"/evidence/case/6df1b8592b6a18.jpg","thumb_url":"/evidence/case/6df1b8592b6a18-t.jpg","relationships":[{"to":"EVID-P25","kind":"PRECEDES","note":"The ticket number recorded here is the one the later power-down log carries."},{"to":"EVID-P06B","kind":"CORROBORATES","note":"Circuit 7 feeds the cameras and the wall clock whose dashes the symbol drawer sat beneath."}]}$nxj$::jsonb, $nxj${"node":"P06b","reliability":"primary","custodian":"Estates Facilities","source":"Science Building plant controller (print)"}$nxj$::jsonb)
