INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P07B$nxs$, $nxs$Copy Map: Symbols to Keepers$nxs$, $nxs$A table matching the three copy symbols to the kind of record and to the custodian who holds it.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"COPY MAP. ⟁ Origin: the copy of what was seen: OBSERVATION, R.N., Rahal. ⧉ Connection: the copy of what was measured, ledgers and tapes: ANALYSIS, M.C., Carter. ⬡ Structure: the copy of what was filed, boxes and custody: VERIFICATION, M.S., Selim. The designer, L.V., holds no copy and appears on no node. The other four symbols label checks.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Lab network diagram, with the 2021 roster","custodian":"Investigating unit","provenance":"Derived from other records","date":"2026-10-07","captured_at":"2026-10-07","condition":"NORMAL","image_url":"/evidence/case/f4b0e11cf95137.jpg","thumb_url":"/evidence/case/f4b0e11cf95137-t.jpg","relationships":[{"to":"EVID-P05","kind":"DERIVES","note":"Roles, initials and what each role holds."},{"to":"EVID-P06B","kind":"DERIVES","note":"Symbol names and the glosses for the first three."}]}$nxj$::jsonb, $nxj${"node":"P07b","reliability":"derived","custodian":"Investigating unit","source":"Lab network diagram, with the 2021 roster"}$nxj$::jsonb)
