INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P14$nxs$, $nxs$Incident Record 037: Index Sheet$nxs$, $nxs$The index sheet of Incident Record 037, with the Registry’s retention stamp.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"INCIDENT RECORD 037, INDEX SHEET. Filing keyword: VECTOR. Signed for the record: N. Rahal, Observation Officer Gr.2, 19 OCT 1994. ITEM 1 p. 1 KS-1. ITEM 2 p. 2 KS-2. ITEM 3 p. 3 KS-3. ITEM 4 no page KS-4. Printed pages follow this sheet: 3. Descriptions of the items are on key sheet KS-037, filed separately. Stamp: RETENTION 30Y FROM DATE OF INCIDENT 14 OCT 1994, EXPIRES 14 OCT 2024. Pencil: pages on file against index, reconcile.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Memory lab terminal (scan)","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"1994-10-19","captured_at":"1994-10-19","condition":"NORMAL","image_url":"/evidence/case/9b9036c8fdf41d.jpg","thumb_url":"/evidence/case/9b9036c8fdf41d-t.jpg","relationships":[{"to":"EVID-P13","kind":"CORROBORATES","note":"The incident date is the night after the first Memory Transfer run."},{"to":"EVID-P18","kind":"PRECEDES","note":"The key sheet describes the numbered rows."}]}$nxj$::jsonb, $nxj${"node":"P14","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Memory lab terminal (scan)"}$nxj$::jsonb)
