INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P15$nxs$, $nxs$Archive Withdrawal Register 1994, Page 3$nxs$, $nxs$Page 3 of the archive’s 1994 withdrawal register, lines 22 to 26 and line 42.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"ARCHIVE WITHDRAWAL REGISTER 1994, PAGE 3 (extract). Line 22: 05 OCT NX-035 box 2, H. Marsh, returned 06 OCT. Line 23: 09 OCT NX-036 box 7, N. Rahal, returned 09 OCT. Line 24: 09 OCT NX-037 boxes 1-3, M. Selim, returned: none. Line 25: 10 OCT NX-034 box 1, M.A. Carter, returned 11 OCT. Line 26: 11 OCT NX-035 box 4, H. Marsh, returned 12 OCT. Line 42: 12 OCT NX-031 box 3, T. Arden, returned 13 OCT. Issued by: archive desk.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Library entrance symbol wall","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"1994-10-12","captured_at":"1994-10-12","condition":"NORMAL","image_url":"/evidence/case/c548337e7dba69.jpg","thumb_url":"/evidence/case/c548337e7dba69-t.jpg","relationships":[{"to":"EVID-P14","kind":"EXPLAINS","note":"The incident record’s source note cites this line by glyph pair."},{"to":"EVID-P16","kind":"PRECEDES","note":"Three days before the briefing."}]}$nxj$::jsonb, $nxj${"node":"P15","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Library entrance symbol wall"}$nxj$::jsonb)
