INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P16$nxs$, $nxs$Briefing Seat Plan, Section B, 12 October 1994$nxs$, $nxs$Seat plan for the Directorate briefing in the main auditorium, Section B, occupied rows only.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"DIRECTORATE BRIEFING, 12 OCT 1994 14:00, MAIN AUDITORIUM. SEAT PLAN, SECTION B. Only occupied rows are drawn, numbered R1 onward in the order drawn. Rows not drawn are empty rows. Seats are numbered 1 to 15 from the aisle. Entries are invitation numbers (INV). R1: seat 6 INV 05, seat 7 INV 06, seat 8 INV 07. R2: seat 1 INV 11, seat 2 INV 12, seat 3 INV 13. R3: seat 9 INV 17, seat 15 INV 18. R4: seat 1 INV 21, seat 2 INV 22, seat 3 INV 23, seat 14 INV 24, seat 15 INV 25. R5: seat 15 INV 31. Unlisted seats empty.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Main auditorium, Section B","custodian":"Directorate desk (Bureau of Continuity Records successor files)","provenance":"Original record; first-hand","date":"1994-10-12","captured_at":"1994-10-12","condition":"NORMAL","image_url":"/evidence/case/d82283bee7effb.jpg","thumb_url":"/evidence/case/d82283bee7effb-t.jpg","relationships":[{"to":"EVID-P16-B","kind":"EXPLAINS","note":"The invitation list turns the numbers into names."}]}$nxj$::jsonb, $nxj${"node":"P16","reliability":"primary","custodian":"Directorate desk (Bureau of Continuity Records successor files)","source":"Main auditorium, Section B"}$nxj$::jsonb)
