INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P16-B$nxs$, $nxs$Invitation List with Personnel Check, 12 October 1994$nxs$, $nxs$The Directorate’s invitation list for the briefing, with a personnel check column.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"INVITATION LIST, DIRECTORATE BRIEFING, 12 OCT 1994 14:00. Issued 10 OCT 1994 by the Directorate desk. Personnel check run against the roster at issue. INV 05-07 (board, 3) Directorate, on file. INV 11-13 (staff, 3) Estates, on file. INV 17 ARDEN, T., Finance, on file. INV 18 HOLLIS, R., Estates, on file. INV 21-23 (project staff, 3) NX-037, on file. INV 24 VALE, A., Directorate desk, on file. INV 25 WRIGHT, D., Directorate, NO SUCH PERSON. INV 31 PRYOR, E., Finance, on file.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Main auditorium, Section B","custodian":"Directorate desk (Bureau of Continuity Records successor files)","provenance":"Original record; first-hand","date":"1994-10-10","captured_at":"1994-10-10","condition":"NORMAL","image_url":"/evidence/case/ae84d522841bc6.jpg","thumb_url":"/evidence/case/ae84d522841bc6-t.jpg","relationships":[{"to":"EVID-P16","kind":"EXPLAINS","note":"Resolves the plan’s invitation numbers into names."},{"to":"EVID-P26","kind":"PRECEDES","note":"The standing instruction that explains the stamp."}]}$nxj$::jsonb, $nxj${"node":"P16","reliability":"primary","custodian":"Directorate desk (Bureau of Continuity Records successor files)","source":"Main auditorium, Section B"}$nxj$::jsonb)
