VALUES ($nxs$EVID-P17$nxs$, $nxs$Tape 7 Excerpt: Pilot and Stop Tones$nxs$, $nxs$A synthesised reconstruction of an excerpt of tape 7 around the 03:17 stop, with both pilot tones on the control track.$nxs$, $nxs$AUDIO$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"TAPE 7 EXCERPT (reconstruction, 17 seconds). [Tone, 1747 Hz.] Spoken: \"Recorder seven. Oh three sixteen. Levels steady.\" [Room tone, 2.5 seconds.] [Tone, 2147 Hz.] [Silence, 3 seconds.] [Tone, 1747 Hz.]","state":"UNREVIEWED","artifact_type":"AUDIO","source":"Auditorium stage terminal","custodian":"Bureau of Continuity Records","provenance":"Derived from other records","date":"1994-10-14 03:17","captured_at":"1994-10-14 03:17","condition":"NORMAL","audio_url":"/audio/case/0ac79aea2afb38.mp3","transcript":"[Tone, 1747 Hz.] CARTER: Recorder seven. Oh three sixteen. Levels steady. [Room tone.] [Tone, 2147 Hz.] [Silence.] [Tone, 1747 Hz.]","relationships":[{"to":"EVID-P17-B","kind":"CORROBORATES","note":"The deck log records an unsigned stop at 03:17."}]}$nxj$::jsonb, $nxj${"node":"P17","reliability":"derived","custodian":"Bureau of Continuity Records","source":"Auditorium stage terminal"}$nxj$::jsonb)
