INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P17-B$nxs$, $nxs$Recorder Log, Tape 7 (IR-037 p. 1)$nxs$, $nxs$The deck log for tape 7, page 1 of Incident Record 037, with its signature column and fault register.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"HALDER INSTITUTE, RECORDER LOG, TAPE 7 (IR-037 p. 1 of 3). 02:48 REC ON, signed, tape 7 loaded, pilot logged. 03:16 CHECK, signed, levels steady. 03:17 STOP, not signed, operator did not sign. 03:24 REC ON, not signed, operator did not sign. Deck fault register: no entries.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Auditorium stage terminal","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"1994-10-14","captured_at":"1994-10-14","condition":"NORMAL","image_url":"/evidence/case/e8f87c80295381.jpg","thumb_url":"/evidence/case/e8f87c80295381-t.jpg","relationships":[{"to":"EVID-P17","kind":"CORROBORATES","note":"The audio carries the stop pilot the specification ties to a received stop."},{"to":"EVID-P14","kind":"EXPLAINS","note":"This is the first of the three printed pages of IR-037."}]}$nxj$::jsonb, $nxj${"node":"P17","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Auditorium stage terminal"}$nxj$::jsonb)
