INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P17B$nxs$, $nxs$Etched Strip: Transcription and Tool-Issue Slip$nxs$, $nxs$A transcription of the copper strip in the auditorium basement with its decoding steps, and the Facilities tool-issue slip for the tape and scribe.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"STRIP AS ETCHED: XGWHGOHLMGVLIMGSXLPFSLLVX (25 letters). Rail fence, 3 rails (7, 12, 6): XLFMGGSVWLLIHMLGGSVXOLXPH. Atbash: COUNTTHEDOORSNOTTHECLOCKS. Read: COUNT THE DOORS NOT THE CLOCKS. FACILITIES TOOL-ISSUE SLIP FT-94-117, 17 OCT 1994. Issued to TECH-11: 1 reel copper tape 25 mm, 1 scribe. Use: notice, auditorium basement pillar. Text length: 25 characters, 6 words, no spaces.","state":"UNREVIEWED","artifact_type":"NOTE","source":"Auditorium basement archive, concrete pillar","custodian":"Estates Facilities","provenance":"Derived from other records","date":"1994-10-17","captured_at":"1994-10-17","condition":"NORMAL","image_url":"/evidence/case/9e1c7f077eaf64.jpg","thumb_url":"/evidence/case/9e1c7f077eaf64-t.jpg","relationships":[{"to":"EVID-P17","kind":"PRECEDES","note":"The person who left the message is the one who handled the tape the stop affected."},{"to":"EVID-P09","kind":"EXPLAINS","note":"A building where one clock runs four hours out of true."}]}$nxj$::jsonb, $nxj${"node":"P17b","reliability":"derived","custodian":"Estates Facilities","source":"Auditorium basement archive, concrete pillar"}$nxj$::jsonb)
