INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P18$nxs$, $nxs$Incident Record 037: Item Key$nxs$, $nxs$Key sheet KS-037 resolved against the NX-037 stock card and personnel annex.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"ITEM KEY (compiled from KS-037 and the NX-037 stock card). Item 1: recorder log, tape 7, printed p. 1. Item 2: operations ledger, extract, printed p. 2. Item 3: photograph B-07, print, printed p. 3. Item 4: a person withdrawn from the project roster by this record, cited SUBJ-nn with nn the line on the personnel annex (box 3); no page printed. Annex line 05: VEY, L.M., Project Lead, WITHDRAWN 19 OCT 1994. Item 4 = SUBJ-05. Boxes: 1 operations ledger, 2 photographic print B-07, 3 personnel annex; no box 4.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Library reading room, fifth-symbol lock","custodian":"Investigating unit","provenance":"Derived from other records","date":"2026-10-07","captured_at":"2026-10-07","condition":"NORMAL","image_url":"/evidence/case/05727aa21c038d.jpg","thumb_url":"/evidence/case/05727aa21c038d-t.jpg","relationships":[{"to":"EVID-P14","kind":"DERIVES","note":"Resolves the numbered rows of the index."},{"to":"EVID-P15","kind":"DERIVES","note":"Boxes 1-3 are the boxes signed out on 09 Oct."},{"to":"EVID-P17-B","kind":"DERIVES","note":"Item 1 is the log on page 1."}]}$nxj$::jsonb, $nxj${"node":"P18","reliability":"derived","custodian":"Investigating unit","source":"Library reading room, fifth-symbol lock"}$nxj$::jsonb)
