INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P19$nxs$, $nxs$Work Order Scrap WO-94-1014-11$nxs$, $nxs$A torn scrap of a Facilities work order assigned to TECH-11, with one pencil entry.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"FACILITIES WORK ORDER WO-94-1014-11 (lower part of sheet; upper part missing). ASSIGNED: TECH-11. RAISED: 14 OCT 1994 03:50. SITE: Admin Building, ground floor. ENTRY (pencil): T7 down the shaft, not the duct. SIGNATURE: torn away.","state":"UNREVIEWED","artifact_type":"NOTE","source":"Sculpture garden","custodian":"Estates Facilities","provenance":"Original record; first-hand","date":"1994-10-14 03:50","captured_at":"1994-10-14 03:50","condition":"TORN","image_url":"/evidence/case/e363484f10f426.jpg","thumb_url":"/evidence/case/e363484f10f426-t.jpg","relationships":[{"to":"EVID-P17-B","kind":"EXPLAINS","note":"The tape halted at 03:17 on the deck log."},{"to":"EVID-P18","kind":"EXPLAINS","note":"T7 is item 1 of the incident record, tape 7."}]}$nxj$::jsonb, $nxj${"node":"P19","reliability":"primary","custodian":"Estates Facilities","source":"Sculpture garden"}$nxj$::jsonb)
