INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P20$nxs$, $nxs$Seal Slip SQ-24-001, front and reverse$nxs$, $nxs$Both sides of the seal slip entered against SQ-24-001, with a per-custodian check grid and a printed legend.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"NEXUS SEAL SLIP SQ-24-001, FRONT AND REVERSE. Applied 17 OCT 2024 21:47. Attested R.N. 21:44, M.C. 21:45, M.S. 21:47. Bound (designer) L.V. Reverse, checks by position: R.N. 1 2 3 4 not-5 6 7; M.C. 1 2 3 4 not-5 6 7; M.S. 1 2 3 4 not-5 6 7. Printed legend: 5 CHOICE. The disposition of the closed record (FILE / SEAL / RETURN) is entered here by the quorum that next convenes. A custodian does not tick 5. The designer does not tick 5.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Dome base, behind the panel","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2024-10-17 21:47","captured_at":"2024-10-17 21:47","condition":"NORMAL","image_url":"/evidence/case/19704603b98549.jpg","thumb_url":"/evidence/case/19704603b98549-t.jpg","relationships":[{"to":"EVID-M01","kind":"EXPLAINS","note":"The front of the slip the team already holds: check 5 blank."},{"to":"EVID-P21","kind":"PRECEDES","note":"The disposal notice was served for the next morning."}]}$nxj$::jsonb, $nxj${"node":"P20","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Dome base, behind the panel"}$nxj$::jsonb)
