INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P21$nxs$, $nxs$Disposal Notice DN-24-107$nxs$, $nxs$The Office of Oversight’s notice of 15 October 2024 ordering the destruction of named items from file NX-037.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"DISPOSAL NOTICE DN-24-107. Office of Oversight, for the Directorate. 15 OCT 2024. File NX-037. Authority: BCR Standing Rule R3.2. The period prescribed under R3.2 for the file named above expired on 14 October 2024. The following are to be destroyed on 18 October 2024 at 10:00: Boxes 1, 2, 3 (operations file), stack B-4. Tape 7, shaft S-3. No other item is named. A. Vale, Oversight Officer. Cover note: Routine disposal on lapse of period. No instruction of any person or office is involved. The authority is stated on the notice.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Fourth-floor window, taped behind the note","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2024-10-15","captured_at":"2024-10-15","condition":"NORMAL","image_url":"/evidence/case/18afe0646c2f08.jpg","thumb_url":"/evidence/case/18afe0646c2f08-t.jpg","relationships":[{"to":"EVID-P21-B","kind":"PRECEDES","note":"The certificate records the execution of this notice."},{"to":"EVID-M03","kind":"EXPLAINS","note":"The rule book resolves the rule number."}]}$nxj$::jsonb, $nxj${"node":"P21","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Fourth-floor window, taped behind the note"}$nxj$::jsonb)
