INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P21-B$nxs$, $nxs$Disposal Certificate DC-24-107$nxs$, $nxs$The certificate of execution for Disposal Notice DN-24-107, dated 18 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"DISPOSAL CERTIFICATE DC-24-107. Executed 18 OCT 2024 10:00 by A. Vale. Witness: Estates security. Box 1, stack B-4, contents —, container destroyed. Box 2, stack B-4, contents —, container destroyed. Box 3, stack B-4, contents —, container destroyed. Tape 7, shaft S-3, NOT LOCATED (shaft inspected).","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Central archive terminal (print)","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2024-10-18 10:00","captured_at":"2024-10-18 10:00","condition":"NORMAL","image_url":"/evidence/case/518e218befb5e5.jpg","thumb_url":"/evidence/case/518e218befb5e5-t.jpg","relationships":[{"to":"EVID-P21-C","kind":"CONTRADICTS","note":"The slip places the contents in Selim’s custody two days earlier."}]}$nxj$::jsonb, $nxj${"node":"P21","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Central archive terminal (print)"}$nxj$::jsonb)
