INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P21-C$nxs$, $nxs$Custody Transfer Slip CT-24-016$nxs$, $nxs$Mara Selim’s custody transfer slip of 16 October 2024 for the contents of boxes 1–3.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"CUSTODY TRANSFER SLIP CT-24-016. Verification register. 16 OCT 2024 16:10. File NX-037 (operations file). From archive stack B-4 to Verification custody, M. Selim. Item: boxes 1, 2, 3, entire contents. Containers returned to stack B-4 as found. Transferred under Charter Art. VI (a custodian may move her own copy). Entered in the custodian’s register only. M. Selim. Handwritten: all of it. MS","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Verification custodian’s register","custodian":"Verification custodian (M. Selim)","provenance":"Original record; first-hand","date":"2024-10-16 16:10","captured_at":"2024-10-16 16:10","condition":"NORMAL","image_url":"/evidence/case/3344187feb9820.jpg","thumb_url":"/evidence/case/3344187feb9820-t.jpg","relationships":[{"to":"EVID-P21-B","kind":"CONTRADICTS","note":"The certificate’s dash is an absence of contents, not an omission."}]}$nxj$::jsonb, $nxj${"node":"P21","reliability":"primary","custodian":"Verification custodian (M. Selim)","source":"Verification custodian’s register"}$nxj$::jsonb)
