INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-M03$nxs$, $nxs$Bureau Standing Rules R3 and IR-037 Stamp$nxs$, $nxs$An extract of the Bureau’s Standing Rules on closed files, with the retention stamp from Incident Record 037.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"BUREAU STANDING RULES, EXTRACT (2019). R3 Closed files. R3.1 A closed case file is under 30-year retention, counted from the date of closure. R3.2 On expiry of the period the Oversight Officer may order the file destroyed on notice. R5 Writs. R5.1 A writ of the Directorate states its own number and is served on the executing clerk. INCIDENT RECORD 037, stamp: CLOSED 14 OCT 1994, RET 30Y.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Central archive terminal (print)","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2019-03-01","captured_at":"2019-03-01","condition":"NORMAL","image_url":"/evidence/case/c94bb28fdd17c1.jpg","thumb_url":"/evidence/case/c94bb28fdd17c1-t.jpg","relationships":[{"to":"EVID-P21","kind":"EXPLAINS","note":"Resolves the authority cited in DN-24-107."},{"to":"EVID-P14","kind":"CORROBORATES","note":"The same 1994 retention stamp on the incident record."}]}$nxj$::jsonb, $nxj${"node":"M03","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Central archive terminal (print)"}$nxj$::jsonb)
