VALUES ($nxs$EVID-P23$nxs$, $nxs$CCTV Still, Engineering Corridor 2, 19:45$nxs$, $nxs$A frame from the Engineering Block corridor recorder showing a figure in a long dark coat.$nxs$, $nxs$IMAGE$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"CCTV STILL, CAM-E3, ENGINEERING BLOCK CORRIDOR 2. 17-10-24 19:45:12. One person in a long dark coat walking away from the camera along the corridor. Recorder ENG-NVR, synced to the master clock.","state":"UNREVIEWED","artifact_type":"SURVEILLANCE","source":"Robotics Bay 1 terminal, recorder ENG-NVR","custodian":"Estates security","provenance":"Original record; first-hand","date":"2024-10-17 19:45","captured_at":"2024-10-17 19:45","condition":"NORMAL","image_url":"/evidence/case/133e4f952a10bb.jpg","thumb_url":"/evidence/case/133e4f952a10bb-t.jpg","relationships":[{"to":"EVID-M01-B","kind":"CONTRADICTS","note":"The bulletin says she has not been seen since 17:30."},{"to":"EVID-P23B","kind":"PRECEDES","note":"The tunnel sensor log gives the entry 13 minutes earlier."}]}$nxj$::jsonb, $nxj${"node":"P23","reliability":"primary","custodian":"Estates security","source":"Robotics Bay 1 terminal, recorder ENG-NVR"}$nxj$::jsonb)
