INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P23B$nxs$, $nxs$Door Sensor Log, S01-TUN$nxs$, $nxs$The building-controls door sensor log for the tunnel head S01-TUN on 17 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"DOOR SENSOR LOG, S01-TUN (Route Delta head), 17 OCT 2024. Reader: key-switch KS-01 (maintenance key). Badge reader: none fitted. 19:32:06 OPEN key-switch. 19:32:11 CLOSED. No other state change 17:00 to 21:00.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Maintenance vent, Robotics Bay 1","custodian":"Architecture (building controls)","provenance":"Original record; first-hand","date":"2024-10-17","captured_at":"2024-10-17","condition":"NORMAL","image_url":"/evidence/case/5c79035652cb5e.jpg","thumb_url":"/evidence/case/5c79035652cb5e-t.jpg","relationships":[{"to":"EVID-P23","kind":"CORROBORATES","note":"19:32 plus a 14-step walk lands within a minute of the 19:45 frame."},{"to":"EVID-P23B-B","kind":"CORROBORATES","note":"The tunnel-head frame at 19:32:08 shows the door ajar."}]}$nxj$::jsonb, $nxj${"node":"P23b","reliability":"primary","custodian":"Architecture (building controls)","source":"Maintenance vent, Robotics Bay 1"}$nxj$::jsonb)
