INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P24$nxs$, $nxs$Three-System Log, 04:15–05:15$nxs$, $nxs$Extracts of the access control, building controls and CCTV logs for the hour from 04:15 on 18 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"THREE-SYSTEM LOG, 18 OCT 2024, 04:15 to 05:15. ACCESS CONTROL (Computer Science): 04:17:09 E-LAB-D1 card L.V. + keypad ACCEPT; 04:20:41 W-COR-D2 card L.V. ACCEPT; 04:41:15 P-PLT-D3 card T.M. ACCEPT. DOOR AND BUILDING CONTROLS (Architecture): 04:15:03 ELC-BANK 7 DE-ENERGISED; 04:17:11 E-LAB-D1 OPEN, 04:17:38 SHUT; 04:20:43 W-COR-D2 OPEN; 04:50:00 HVAC-E step 2; 05:15:00 ELC-BANK 7 RE-ENERGISED. CCTV (Human Communication): no entries 04:15:03 to 05:15:06; last entry 04:15:02, next 05:15:07.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Antenna deck console","custodian":"Computer Science, Architecture, Human Communication","provenance":"Original record; first-hand","date":"2024-10-18","captured_at":"2024-10-18","condition":"NORMAL","image_url":"/evidence/case/7e0cff02dbe34e.jpg","thumb_url":"/evidence/case/7e0cff02dbe34e-t.jpg","relationships":[{"to":"EVID-P06B","kind":"CORROBORATES","note":"The lab UPS log shows circuit 7 dropping at 04:15:03."}]}$nxj$::jsonb, $nxj${"node":"P24","reliability":"primary","custodian":"Computer Science, Architecture, Human Communication","source":"Antenna deck console"}$nxj$::jsonb)
