INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P24B$nxs$, $nxs$REC-19 Statements and Logs$nxs$, $nxs$The opening statements segment of recording REC-19, with the bank 7 maintenance log and the access log for L.V.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"REC-19 STATEMENTS, 18 OCT 2024, 04:31 to 04:34. DR. VALE: I reviewed the east laboratory security footage at 04:17 and confirmed Dr. Vey was present. DR. VEY: I was in the east lab when the containment breach alarm sounded at 04:17. MARA SELIM: I saw Dr. Vey in the west corridor at 04:20. NOOR RAHAL: The east laboratory cameras were powered down for maintenance beginning at 04:15. BANK 7 LOG: 04:15:03 de-energised, no frames after 04:15:02; 05:15:00 re-energised, first frame 05:15:07. ACCESS LOG L.V.: 04:17:09 E-LAB-D1 badge + keypad; 04:20:41 W-COR-D2 badge.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Antenna deck interrogation room","custodian":"N. Rahal (REC-19); Facilities; Computer Science","provenance":"Original record; first-hand","date":"2024-10-18 04:31","captured_at":"2024-10-18 04:31","condition":"NORMAL","image_url":"/evidence/case/1c439e04d2c572.jpg","thumb_url":"/evidence/case/1c439e04d2c572-t.jpg","relationships":[{"to":"EVID-P24","kind":"EXPLAINS","note":"The empty recording log is the cut that makes the footage claim impossible."},{"to":"EVID-P25","kind":"PRECEDES","note":"The ticket behind the cut."}]}$nxj$::jsonb, $nxj${"node":"P24b","reliability":"primary","custodian":"N. Rahal (REC-19); Facilities; Computer Science","source":"Antenna deck interrogation room"}$nxj$::jsonb)
