INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P25$nxs$, $nxs$Maintenance Ticket MT-24-3302$nxs$, $nxs$The Facilities maintenance ticket for the removal of supply to electrical bank 7 on the morning of 18 October 2024.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"MAINTENANCE TICKET MT-24-3302. Raised 17 OCT 2024 23:52. Unit: ELC-BANK 7 (circuit 7: CCTV head-end HE-1, wall clocks). Work: remove supply. Reason: inspection of head-end HE-1. Window: 18 OCT 04:15 to 05:15. Requested by: (blank). AUTH: D. WRIGHT (handwritten). EXEC: A. VALE. Filed 18 OCT 2024 05:20, Facilities.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Server rack cooling fan assembly, cooling corridor","custodian":"Facilities","provenance":"Original record; first-hand","date":"2024-10-17 23:52","captured_at":"2024-10-17 23:52","condition":"NORMAL","image_url":"/evidence/case/51cb3eeb9f911f.jpg","thumb_url":"/evidence/case/51cb3eeb9f911f-t.jpg","relationships":[{"to":"EVID-P24B","kind":"EXPLAINS","note":"The cut that made Vale’s footage claim impossible."},{"to":"EVID-P26","kind":"EXPLAINS","note":"Standing Instruction 7 accounts for the authorising line."}]}$nxj$::jsonb, $nxj${"node":"P25","reliability":"primary","custodian":"Facilities","source":"Server rack cooling fan assembly, cooling corridor"}$nxj$::jsonb)
