INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P26$nxs$, $nxs$Standing Instruction 7$nxs$, $nxs$The Directorate’s standing instruction on the issue and completion of writ D-W.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"DIRECTORATE STANDING INSTRUCTION 7, issued 1987, revision 3 (2019). Writ D-W is issued pre-signed by the Secretary with the line AUTHORISING OFFICER left blank. The executing clerk enters D. WRIGHT in the prescribed hand. No individual is to be named. The entry shall be uniform across clerks.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Holographic lab, optical bench casing","custodian":"The Directorate","provenance":"Original record; first-hand","date":"2019-03-01","captured_at":"2019-03-01","condition":"NORMAL","image_url":"/evidence/case/bfa11d515ad604.jpg","thumb_url":"/evidence/case/bfa11d515ad604-t.jpg","relationships":[{"to":"EVID-P25","kind":"EXPLAINS","note":"Accounts for the authorising line on the 2024 ticket."},{"to":"EVID-P16","kind":"EXPLAINS","note":"Accounts for the NO SUCH PERSON stamp on the 1994 roster."}]}$nxj$::jsonb, $nxj${"node":"P26","reliability":"primary","custodian":"The Directorate","source":"Holographic lab, optical bench casing"}$nxj$::jsonb)
