INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P27$nxs$, $nxs$Disposal Notice DN-24-107, schedule (annotated)$nxs$, $nxs$The schedule page of the disposal notice of 15 October 2024, with a reviewer’s marginal notes.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"DISPOSAL NOTICE DN-24-107, SCHEDULE. Issued 15 OCT 2024, Oversight desk (A. Vale). Authority: 30-year retention on closed file NX-037, expired 14 OCT 2024. Item 1: NX-037 operations file, boxes 1 to 3, Archive. Item 2: magnetic tape 7, recorder log R-94-07, shaft S-3. Execute 18 OCT 2024, 10:00. Certificate DC-24-107 to follow. This notice reaches the holdings listed above and no others. A holding not listed is outside it. Reviewer’s notes in blue: item 1 = filed copy; item 2 = measured copy; seen copy: nothing listed.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Architecture lab server terminal (print)","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2024-10-15","captured_at":"2024-10-15","condition":"NORMAL","image_url":"/evidence/case/30e3723141bd04.jpg","thumb_url":"/evidence/case/30e3723141bd04-t.jpg","relationships":[{"to":"EVID-P07B","kind":"DERIVES","note":"The copy map allots the listed items to the Verification and Analysis copies."},{"to":"EVID-P21","kind":"CORROBORATES","note":"The certificate that followed the notice found boxes 1 to 3 empty."}]}$nxj$::jsonb, $nxj${"node":"P27","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Architecture lab server terminal (print)"}$nxj$::jsonb)
