INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P27B$nxs$, $nxs$Camera-Controller Trace, ELC-BANK (annotated)$nxs$, $nxs$The execution trace of the east-lab camera-bank controller with each line tested against the state table.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"ELC-BANK CONTROLLER TRACE, tested against the state table. [0] R0 0, input 0x01: table gives 1, next register 1, OK. [1] R1 1, input 0x02: table gives 3 (FAULT), next register shows 2 (BUFFERING), FAILS. [2] R2 2, input 0x01: table gives 3, next register 3, OK. [3] R3 3, input 0x02: table gives 2, next register 2, OK. [4] R4 2, DONE. Command index: [0] 04:15:03 ticket MT-24-3302; [1] 04:15:09 scheduler; [2] 05:15:00 facilities restore; [3] 05:15:04 scheduler. Camera-system log: no frames 04:15:03 to 05:15:04.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Architecture lab debug console","custodian":"Bureau of Continuity Records","provenance":"Derived from other records","date":"2024-10-18","captured_at":"2024-10-18","condition":"NORMAL","image_url":"/evidence/case/a0e250209fc746.jpg","thumb_url":"/evidence/case/a0e250209fc746-t.jpg","relationships":[{"to":"EVID-P25","kind":"CONTRADICTS","note":"The ticket cut power at 04:15:03; the altered line has the bank recording afterwards."},{"to":"EVID-P24B","kind":"EXPLAINS","note":"A line of this kind would let a statement about 04:17 footage look supported."}]}$nxj$::jsonb, $nxj${"node":"P27b","reliability":"derived","custodian":"Bureau of Continuity Records","source":"Architecture lab debug console"}$nxj$::jsonb)
