INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P28$nxs$, $nxs$REC-19, fragment 5 of 5$nxs$, $nxs$The fifth fragment cut from the pocket recorder’s reel: a repeated question, a bell, and the room at first light.$nxs$, $nxs$AUDIO$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"REC-19 fragment 5 of 5, about 46 seconds. Footsteps. A male voice (VOICE A) asks for the custodians’ names. Keys. Vey says she will tell what she is sure of. The tower bell strikes five times. Vey says nobody keeps it all, not the questioner and not her. Birdsong. A second male voice (VOICE B) says it is getting light. VOICE A asks again. Vey answers that the answer will be the same when the sun is up. Footsteps.","state":"UNREVIEWED","artifact_type":"AUDIO","source":"Fragment container, research chamber","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2024-10-18","captured_at":"2024-10-18","condition":"NORMAL","audio_url":"/audio/case/c40d245e3f862d.mp3","transcript":"[footsteps] VOICE A: The custodians. Give me their names. [keys] VEY: You want names. I will tell you what I am sure of. [the tower bell strikes five times] VEY: Nobody keeps it all. Not you. Not me. [birdsong] VOICE B: It is getting light. Finish this. VOICE A: The custodians, Doctor. Again. VEY: Ask me when the sun is up. The answer will be the same. [footsteps]","relationships":[{"to":"EVID-P28-B","kind":"EXPLAINS","note":"The recorder log gives the span of the reel that this fragment was cut from."},{"to":"EVID-P24B","kind":"PRECEDES","note":"The earlier excerpt is cut from the same reel."}]}$nxj$::jsonb, $nxj${"node":"P28","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Fragment container, research chamber"}$nxj$::jsonb)
