INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P28-B$nxs$, $nxs$Pocket Recorder Log, REC-19$nxs$, $nxs$The log card kept with the recorder for reel A, with the five fragments cut for the file.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"POCKET RECORDER LOG, REC-19. Reel A, micro-cassette, 70 minutes, continuous. REC-19 start 04:30. REC-19 stop 05:40. Recorder clock set to building time at 04:12. Carried inside the jacket, left breast pocket. Operator: facilities. Fragments cut for the file, in the order recorded: F1 first question, tape 7. F2 second question, the boxes. F3 third question, the custodians. F4 fourth question, C214-X. F5 repeat of the third question; ambience: window grey, birds. No other reel was running in the room.","state":"UNREVIEWED","artifact_type":"NOTE","source":"Fragment container, research chamber","custodian":"Facilities","provenance":"Original record; first-hand","date":"2024-10-18","captured_at":"2024-10-18","condition":"NORMAL","image_url":"/evidence/case/c96d94cb513438.jpg","thumb_url":"/evidence/case/c96d94cb513438-t.jpg","relationships":[{"to":"EVID-P28","kind":"EXPLAINS","note":"The span fixes which five the bell was striking."}]}$nxj$::jsonb, $nxj${"node":"P28","reliability":"primary","custodian":"Facilities","source":"Fragment container, research chamber"}$nxj$::jsonb)
