INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P29$nxs$, $nxs$Declassified Design Note, NEXUS rev 3$nxs$, $nxs$The classified memo NX/CLS/12 with its result line restored.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"CLASSIFIED MEMO // PROJECT NEXUS. Control NX/CLS/12. Subject: Entity identification. Result: A RECORDS PROTOCOL. NEXUS is not a database on a disk. The key relationship: a fact is closed when three independent custodians, each holding a separate copy, agree. It stores nothing of its own and it cannot run with fewer than three. Asked a question, it returns only what three people agree is true. Class changed from A to P, rev 3. Marginal note in red: Directorate requirement was a system that says what it is told. Not met. Signed: L. Vey, designer.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Core declassification vault","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2021-12-01","captured_at":"2021-12-01","condition":"NORMAL","image_url":"/evidence/case/dc9ae86b5cbe41.jpg","thumb_url":"/evidence/case/dc9ae86b5cbe41-t.jpg","relationships":[{"to":"EVID-P04","kind":"EXPLAINS","note":"The sessions that closed had three attestations because the rule needs three."},{"to":"EVID-P05","kind":"EXPLAINS","note":"The designer holds no copy because the rule does not allow a fourth holder."}]}$nxj$::jsonb, $nxj${"node":"P29","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Core declassification vault"}$nxj$::jsonb)
