  classification = EXCLUDED.classification, content = EXCLUDED.content, metadata = EXCLUDED.metadata;
INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-M04$nxs$, $nxs$Building Alarm Log AL-241018, east lab (annotated)$nxs$, $nxs$An extract of the building alarm log for the east laboratory at 04:17 on 18 October 2024, with a reviewer’s notes.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"BUILDING ALARM LOG AL-241018, east lab, extract. SEQ 3181 04:17 E-LAB-D1 badge read L.V., code accepted. SEQ 3182 04:17 E-LAB-D1 alarm: containment breach. Source: manual, Oversight console. Sensors: door forced none, motion none, tamper none. Video confirmation: attached by operator. A sensor alarm shows at least one tripped sensor. A manual alarm shows none. The log does not record the name of the operator of a manual alarm. Reviewer’s notes in blue: cameras dark since 04:15:03; confirmation cannot exist.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Vault Delta terminal (print)","custodian":"Estates security","provenance":"Original record; first-hand","date":"2024-10-18","captured_at":"2024-10-18","condition":"NORMAL","image_url":"/evidence/case/3dc9651c52a477.jpg","thumb_url":"/evidence/case/3dc9651c52a477-t.jpg","relationships":[{"to":"EVID-P27B","kind":"CONTRADICTS","note":"The alarm cites video confirmation; the cameras were dark and the trace line that suggests otherwise was altered."},{"to":"EVID-P25","kind":"PRECEDES","note":"The ticket that cut the cameras was executed two minutes before the alarm."},{"to":"EVID-P24B","kind":"CORROBORATES","note":"A statement of footage seen at 04:17 is the only support the alarm has."}]}$nxj$::jsonb, $nxj${"node":"M04","reliability":"primary","custodian":"Estates security","source":"Vault Delta terminal (print)"}$nxj$::jsonb)
