  title = EXCLUDED.title, description = EXCLUDED.description, type = EXCLUDED.type,
  classification = EXCLUDED.classification, content = EXCLUDED.content, metadata = EXCLUDED.metadata;
INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P31$nxs$, $nxs$REC-19 Transcript, selected lines$nxs$, $nxs$Selected lines of the REC-19 transcript in which her questioners put a master copy to her and she answers.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"REC-19 TRANSCRIPT, selected lines. F2 VOICE A: You designed it. You hold the master copy. F2 VEY: I hold nothing. That is the design. F3 VOICE A: Then who holds it? F3 VEY: Three who do not know what the others hold. F4 VOICE B: Where is the original, Doctor? F4 VEY: There is no original. There are three, and I am none of them. F5 VEY: Nobody keeps it all. Not you. Not me.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Memory array terminal (print)","custodian":"Bureau of Continuity Records","provenance":"Official statement; not independently checked","date":"2024-10-18","captured_at":"2024-10-18","condition":"NORMAL","image_url":"/evidence/case/bb4467d01a8763.jpg","thumb_url":"/evidence/case/bb4467d01a8763-t.jpg","relationships":[{"to":"EVID-P07B","kind":"CORROBORATES","note":"The copy map lists three copies and three keepers, none of them the designer."},{"to":"EVID-P28","kind":"EXPLAINS","note":"Fragment 5 carries the last line quoted here."}]}$nxj$::jsonb, $nxj${"node":"P31","reliability":"secondary","custodian":"Bureau of Continuity Records","source":"Memory array terminal (print)"}$nxj$::jsonb)
