INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P32$nxs$, $nxs$Negative Strip, FIELD-CAM-02, 13/14 October 1994$nxs$, $nxs$A strip of three frames from the handheld second camera, including the frame stamped 03:17:11.$nxs$, $nxs$IMAGE$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"NEGATIVE STRIP, FIELD-CAM-02, night of 13/14 October 1994. Three frames: the corridor at 03:12, empty; frame B-07 stamped 03:17:11, a figure at the corridor mouth; a third frame. The recorder (tape 7) was stopped 03:17 to 03:24 by writ; the writ named tape 7 only.","state":"UNREVIEWED","artifact_type":"PHOTOGRAPH","source":"Final vault, holographic projector","custodian":"Observation copy, N. Rahal","provenance":"Original record; first-hand","date":"1994-10-14","captured_at":"1994-10-14","condition":"NORMAL","image_url":"/evidence/case/4d3b648c55cf8f.jpg","thumb_url":"/evidence/case/4d3b648c55cf8f-t.jpg","relationships":[{"to":"EVID-P17","kind":"CONTRADICTS","note":"The recorder was stopped by command; this camera was not."},{"to":"EVID-P16","kind":"EXPLAINS","note":"The writ was a pre-signed form that named tape 7 only."}]}$nxj$::jsonb, $nxj${"node":"P32","reliability":"primary","custodian":"Observation copy, N. Rahal","source":"Final vault, holographic projector"}$nxj$::jsonb)
