INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P33$nxs$, $nxs$Bulletin MP-24-018, annotated$nxs$, $nxs$The Bureau’s bulletin of 18 October 2024, clause by clause, with the records that bear on each clause.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"BULLETIN MP-24-018, 18 OCT 2024 09:40, annotated. C1 Dr. L. Vey left the Admin Building. C2 at 17:30 on 17 October. [Annotation: guard desk GD-241017 17:28 OUT L.V.; CAM-01 17:29.] C3 She has not been seen since. [Annotation: contradicted by List A, items 1 to 8.] C4 Any information to the Oversight Officer, A. Vale. C5 Issued under the authority of the Directorate. LIST A: 1 19:32 S01-TUN, no badge. 2 19:45 CAM-E3 corridor image. 3 21:47 seal slip, bound L.V. 4 04:17 E-LAB-D1 badge and code. 5 early 18 Oct, Selim, west corridor, own hand. 6 05:00 REC-19, tower strikes five. 7 05:52 S01-TUN OUT. 8 29 SEP 2026 voicemail. Excluded: library slip 44721 (true time 17:22).","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Working copy, second set of custodians","custodian":"Second set of custodians","provenance":"Derived from other records","date":"2026-09-30","captured_at":"2026-09-30","condition":"NORMAL","image_url":"/evidence/case/ce2d1dc74fc880.jpg","thumb_url":"/evidence/case/ce2d1dc74fc880-t.jpg","relationships":[{"to":"EVID-M01-B","kind":"EXPLAINS","note":"The original bulletin, unannotated."},{"to":"EVID-P23","kind":"CORROBORATES","note":"List A item 2 is the 19:45 corridor image."},{"to":"EVID-P30","kind":"CORROBORATES","note":"List A item 8 is the 2026 voicemail."}]}$nxj$::jsonb, $nxj${"node":"P33","reliability":"derived","custodian":"Second set of custodians","source":"Working copy, second set of custodians"}$nxj$::jsonb)
