INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P35$nxs$, $nxs$Record of Choice, Check 5$nxs$, $nxs$A form for the fifth check of seal SQ-24-001 listing three options, none ticked.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"RECORD OF CHOICE, SQ-24-001, CHECK 5 (CHOICE). Prepared for the second set of custodians. [ ] FILE. [ ] SEAL. [ ] RETURN. This form takes no tick. What is chosen is held by those who chose it. Charter CL. 9: a check is closed when three custodians confirm it. The word entered by the verifying seat is AGREE. Entered before all three have confirmed, it is void. First set: checks 1 2 3 4 6 7 ticked; check 5 left for the second set. Second set: OBSERVATION [ ] ANALYSIS [ ] VERIFICATION [ ].","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Final boss chamber terminal","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2021-12-04","captured_at":"2021-12-04","condition":"NORMAL","image_url":"/evidence/case/d588f471a2c9f3.jpg","thumb_url":"/evidence/case/d588f471a2c9f3-t.jpg","relationships":[{"to":"EVID-M01","kind":"EXPLAINS","note":"The seal slip’s unticked fifth check, for which this form exists."},{"to":"EVID-P20","kind":"EXPLAINS","note":"The unticked check identified at the dome."}]}$nxj$::jsonb, $nxj${"node":"P35","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Final boss chamber terminal"}$nxj$::jsonb)
