INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P36$nxs$, $nxs$Voicemail Transcript, 29 September 2026$nxs$, $nxs$The Bureau line transcript of a 41-second voicemail from a withheld number, with one dropout.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"BUREAU LINE, VOICEMAIL TRANSCRIPT. 29 SEP 2026, withheld number, 00:41. [tone] \"This is Lina Vey. It is the twenty-ninth of September. I am leaving this on the Bureau line because it is the one line nobody forwards. I hold no copy of anything. That was always the design. The first three can be accused of being interested. They are. So am I. I am asking the Bureau for a second [DROPOUT 1.1 s]: three people who were not in that building, who attested nothing, who have nothing to gain. One check is still open, and it is not mine to tick. I will not tell them what to do with it.\" [click] Desk entry, in hand: class SECOND QUORUM.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Observation deck broadcast channel (print)","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2026-09-29 19:06","captured_at":"2026-09-29 19:06","condition":"PARTIAL","image_url":"/evidence/case/8d49d6283183af.jpg","thumb_url":"/evidence/case/8d49d6283183af-t.jpg","relationships":[{"to":"EVID-P36-B","kind":"EXPLAINS","note":"The retention desk’s message about the call and the class of request."},{"to":"EVID-P30","kind":"CORROBORATES","note":"The voicemail audio identified at the transmitter spire."}]}$nxj$::jsonb, $nxj${"node":"P36","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Observation deck broadcast channel (print)"}$nxj$::jsonb)
