INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P36-B$nxs$, $nxs$Retention Desk Message RD-26-0929/1$nxs$, $nxs$The retention desk’s internal message about the 29 September 2026 call, with the classes of request.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"BUREAU RETENTION DESK, MESSAGE RD-26-0929/1. Received on the Bureau line 29 SEP 2026 19:06, withheld number, 41 s. Desk closed at 18:00; not answered. The caller names herself and makes one request; the word that names it is lost to a dropout of 1.1 s after \"a second\". A request is accepted only under a named class. Classes: EXTENSION (one officer, lengthens retention); APPEAL (one reviewer named by the Directorate, contests a disposal); AMENDMENT (the same three custodians, in writing, corrects a record); SECOND QUORUM (a further three, none of whom attested the first, convened to finish a check the first left open). Not copied to Oversight. No reply possible. Retention Desk.","state":"UNREVIEWED","artifact_type":"NOTE","source":"Observation deck broadcast channel","custodian":"Bureau of Continuity Records","provenance":"Original record; first-hand","date":"2026-09-30 08:10","captured_at":"2026-09-30 08:10","condition":"NORMAL","image_url":"/evidence/case/a854fd4e47cab1.jpg","thumb_url":"/evidence/case/a854fd4e47cab1-t.jpg","relationships":[{"to":"EVID-P36","kind":"EXPLAINS","note":"The desk’s account of the call transcribed there."}]}$nxj$::jsonb, $nxj${"node":"P36","reliability":"primary","custodian":"Bureau of Continuity Records","source":"Observation deck broadcast channel"}$nxj$::jsonb)
ON CONFLICT (code) DO UPDATE SET
  title = EXCLUDED.title, description = EXCLUDED.description, type = EXCLUDED.type,
