INSERT INTO evidence (code, title, description, type, classification, content, metadata)
VALUES ($nxs$EVID-P37$nxs$, $nxs$Certificate of Closure$nxs$, $nxs$A certificate for check 5 of seal SQ-24-001, recording that it was closed by a second set of three.$nxs$, $nxs$DOCUMENT$nxs$::evidence_type, $nxs$RESTRICTED$nxs$::evidence_classification, $nxj${"text":"CERTIFICATE OF CLOSURE. Seal SQ-24-001, applied 17 OCT 2024 21:47. Check 5 (CHOICE), left open by the first set, was closed on 30 SEP 2026 by a second set of three: OBSERVATION, ANALYSIS, VERIFICATION. Checks 1 to 7: closed. Choice entered: none recorded. The rule: a fact is closed when three independent keepers, each holding a separate copy and none able to see the others’, say the same. What three do with a closed record is not recorded here.","state":"UNREVIEWED","artifact_type":"DOCUMENT","source":"Final boss arena terminal (print)","custodian":"Bureau of Continuity Records","provenance":"Derived from other records","date":"2026-09-30","captured_at":"2026-09-30","condition":"NORMAL","image_url":"/evidence/case/da50b1fbe9a10e.jpg","thumb_url":"/evidence/case/da50b1fbe9a10e-t.jpg","relationships":[{"to":"EVID-P35","kind":"DERIVES","note":"The Record of Choice this certificate closes."},{"to":"EVID-M01","kind":"DERIVES","note":"The seal slip whose fifth check was left open."}]}$nxj$::jsonb, $nxj${"node":"P37","reliability":"derived","custodian":"Bureau of Continuity Records","source":"Final boss arena terminal (print)"}$nxj$::jsonb)
